  "ab": "starting from",
  "Ab B1 lernt man außerhalb des Kurses": "From B1, learning happens outside the classroom",
  "Ab drei Stunden Verspätung besteht meist Anspruch auf Entschädigung, ab zwei Stunden auf Verpflegung. Bei Gepäckverlust: 21 Tage Meldefrist. Die Zauberformel am Schalter: *¿Tengo derecho a compensación?*": "For delays over three hours, you usually have a right to compensation, and for over two hours, to refreshments. For lost luggage: report within 21 days. The magic phrase at the counter: *¿Tengo derecho a compensación?*",
  "Ab dreißig wird getrennt geschrieben": "From thirty onwards, write separately",
  "Ab Mai arbeite ich weniger.": "Starting in May, I work less.",
  "ab und zu": "now and then",
  "Ab und zu gehe ich ins Kino.": "I go to the movies from time to time.",
  "Ab zweihundert passt sich die Zahl an: *doscientos euros*, aber *doscientas personas*. Drei sind unregelmäßig und müssen gelernt werden: *quinientos* (500), *setecientos* (700), *novecientos* (900).": "From two hundred onwards, the number agrees: *doscientos euros*, but *doscientas personas*. Three are irregular and need to be learned: *quinientos* (500), *setecientos* (700), *novecientos* (900).",
  "abbiegen": "turn",
  "Abends kommt Besuch, der viel isst": "Guests are coming in the evening who eat a lot",
  "aber": "but",
  "Aber die Schuhe sind nicht bequem.": "But the shoes aren't comfortable.",
  "Aber in den großen Städten hält unter der Woche kaum jemand Siesta. Die Leute arbeiten in Büros und haben keine Zeit, nach Hause zu fahren.": "But in big cities, hardly anyone takes a siesta during the week. People work in offices and don't have time to go home.",
  "Aber sagtest du nicht, der Ort sei immer estar?": "But didn't you say location always uses estar?",
  "Aber so lerne ich nicht, was ich falsch sage.": "But that's how I learn what I'm saying wrong.",
  "Aberglaube und Bräuche": "Superstitions and customs",
  "abgeben": "submit",
  "abgemacht": "deal done",
  "Abgemacht! Ich reserviere.": "Deal! I'll make a reservation.",
  "Abgemacht. Hoffentlich mache ich nicht wieder Überstunden.": "Deal. Hopefully, I won't end up working late again.",
  "Abgeschlossen und benannt → Indefinido: *ayer*, *la semana pasada*, *en 2020*, *hace tres días*. Noch laufend → Perfekt: *hoy*, *esta semana*, *este año*. Wer die Angabe kennt, muss über die Form nicht mehr nachdenken.": "Completed and named → Preterite: *ayer* (yesterday), *la semana pasada* (last week), *en 2020* (in 2020), *hace tres días* (three days ago). Still ongoing → Present Perfect: *hoy* (today), *esta semana* (this week), *este año* (this year). If you know the time expression, you don't have to think about the tense.",
  "Abheben, wechseln, aufpassen": "Withdraw, Exchange, Beware",
  "abrí": "opened",
