  "ach komm!": "come on!",
  "Ach nichts, ich bin noch hier.": "Not much, just hanging in there.",
  "Ach nichts, viel Arbeit. Du siehst ja.": "Oh, nothing much, lots of work. You know how it is.",
  "Ach, erinner mich nicht dran. Was für ein Tag.": "Oh, don't remind me. What a day.",
  "ach, nichts Besonderes": "oh, nothing much",
