  "Adjektive an Geschlecht und Zahl anpassen": "Adjusting adjectives for gender and number",
  "Adjektive angleichen": "Matching adjectives",
  "Adjektive angleichen und stellen": "Matching and placing adjectives",
  "Adjektive auf *-o* wechseln zu *-a* und bilden die Mehrzahl: *rojo, roja, rojos, rojas*. Solche auf *-e* oder Konsonant kennen kein Geschlecht, nur die Zahl: *verde, verdes*, *azul, azules*.": "Adjectives ending in *-o* change to *-a* for feminine and form plurals: *rojo, roja, rojos, rojas*. Those ending in *-e* or a consonant don't change for gender, only number: *verde, verdes*, *azul, azules*.",
  "Adjektive erkennen, die ihre Bedeutung wechseln": "Identify adjectives that change meaning",
  "Adleraugen haben": "to have eagle eyes",
  "Ah, da war ich schon weg.": "Ah, I had already left by then.",
  "Ah, dann ist gut. Gehen wir zu Fuß?": "Ah, that's good. Are we walking?",
  "Ah, dann ist trabajo auch schwer für mich.": "Ah, then trabajo is also hard for me.",
