  "Alle drei ziehen den Infinitiv nach sich – nur tener braucht das que dazwischen.": "All three are followed by the infinitive – only tener needs que in between.",
  "Alle kennen die Siesta: nach dem Essen ein Weilchen schlafen. In kleinen Dörfern schließen viele Läden mittags immer noch und öffnen nachmittags wieder.": "Everyone knows the siesta: a nap after lunch. In small villages, many shops still close at midday and reopen in the afternoon.",
