  "Alles zusammen: eine Reise von Anfang bis Ende": "All Together: A Trip from Start to Finish",
  "Alles, was bewertet statt berichtet, verlangt ihn: *me alegro de que*, *es una pena que*, *es normal que*, *me molesta que*. Der Nebensatz nennt keine Tatsache, sondern das, worauf sich das Gefühl richtet.": "Anything that evaluates instead of reports requires it: *me alegro de que*, *es una pena que*, *es normal que*, *me molesta que*. The subordinate clause doesn't state a fact but what the feeling is about.",
  "Alles. Am Ende habe ich es gemerkt, und das war es.": "Everything. In the end, I noticed it, and that was it.",
