  "am Anfang": "at the beginning",
  "Am Anfang bin ich schüchtern.": "I'm shy at first.",
  "Am Anfang habe ich ihn nicht erkannt, er trägt jetzt einen Bart.": "At first, I didn't recognize him; he has a beard now.",
  "Am Anfang habe ich nichts verstanden.": "At first, I didn't understand anything.",
  "Am Anfang habe ich sie nicht erkannt.": "At first, I didn't recognize her.",
  "Am Anfang schon. Nach und nach. Gib nicht auf.": "At first, yes. Gradually. Don't give up.",
  "Am Anfang war er nicht elegant. Man tanzte auf der Straße und in den Bars. Erst später kam er in die Säle und danach in den Rest der Welt.": "At first, it wasn't elegant. People danced in the streets and bars. Only later did it move to ballrooms and then the rest of the world.",
  "Am Arbeitsplatz": "At the workplace",
  "Am Automaten Geld abheben": "Withdrawing money from an ATM",
  "Am Bahnhof": "At the train station",
  "Am beeindruckendsten sind die Mauern. Die Steine sind so genau zugeschnitten, dass sie ohne Zement ineinanderpassen. Zwischen zwei Steine passt nicht einmal ein Blatt Papier.": "The most impressive are the walls. The stones are so precisely cut that they fit together without cement. Not even a sheet of paper fits between two stones.",
  "Am besten fährt man mit der Metro.": "The best thing is to take the subway.",
  "Am besten funktioniert die Struktur.": "The structure works best.",
  "Am besten gefällt mir, dass die Leute so viel reden.": "What I like most is that people talk so much.",
  "Am besten gefiel mir der Markt.": "What I liked the most was the market.",
  "Am besten gefiel mir der Süden.": "What I liked the most was the south.",
  "Am besten gefiel mir ein kleines Dorf.": "I liked a small village the most.",
  "am besten ist": "the best is",
  "am Ende": "in the end",
  "Am Ende des Kurses": "At the end of the course",
  "Am Ende hatten wir es großartig.": "In the end, we had a great time.",
  "Am Ende kamen wir rechtzeitig an.": "In the end, we got there on time.",
  "am Ende renkte es sich ein": "it worked out in the end",
  "Am Ende renkte sich alles ein.": "In the end, everything worked out.",
  "Am Ende schaffte ich es, es zu öffnen.": "In the end, I managed to open it.",
  "Am Ende versteht man sich trotzdem.": "In the end, you understand it anyway.",
  "Am Ende versteht man sich trotzdem. Das zählt.": "In the end, you still understand each other. That's what matters.",
  "Am Ende war es nicht so schlimm.": "In the end, it wasn't that bad.",
  "Am Flughafen": "At the airport",
  "Am Meer": "By the sea",
  "Am Montag arbeite ich.": "I work on Monday.",
  "Am Montag fange ich den Kurs an.": "I start the course on Monday.",
  "Am Nachmittag davor gibt es einen Umzug durch die Stadt. Die Könige fahren auf Wagen und werfen den Kindern Bonbons zu, die mit Tüten auf der Straße warten.": "The afternoon before, there's a parade through the city. The kings ride on floats and toss candies to children waiting with bags on the street.",
  "Am nächsten Tag. Und der Flug hatte Verspätung.": "The next day. And the flight was delayed.",
  "Am Samstag gehen wir an den Strand. Kommst du mit?": "We're going to the beach on Saturday. Are you coming?",
  "Am Samstag gehen wir ins Kino.": "We're going to the movies on Saturday.",
  "Am Samstag mache ich eine Party. Ich werde dreißig.": "I'm having a party on Saturday. I'm turning thirty.",
  "Am Schalter einchecken": "Check in at the counter",
  "Am schwersten fiel mir der Subjuntivo.": "The hardest part for me was the Subjunctive.",
  "Am Strand zurechtkommen": "Getting by at the beach",
  "Am Telefon buchstabiert man mit Städtenamen: *B de Barcelona*, *V de Valencia*, *H de Huelva*. Besonders wichtig bei *b* und *v*, die gleich klingen – deshalb die ständige Rückfrage *¿be o uve?*": "On the phone, you spell using city names: *B de Barcelona*, *V de Valencia*, *H de Huelva*. This is especially important for *b* and *v*, which sound similar – hence the frequent question *¿be o uve?*",
  "Am Telefon und per Nachricht": "On the Phone and Messaging",
  "Am Tresen ist es billiger.": "It's cheaper at the bar.",
  "am Vormittag": "in the morning",
  "am wahrscheinlichsten": "most likely",
  "Am wahrscheinlichsten wusste er es nicht.": "Most likely, he didn't know.",
  "Am weichsten: *Yo que tú…* (an deiner Stelle). Mittel: *Deberías…* (du solltest). Am stärksten: *Tienes que…* (du musst). Und ganz unpersönlich: *Hay que…* (man muss) – damit rätst du, ohne jemanden anzusprechen.": "Softest: *Yo que tú…* (if I were you). Medium: *Deberías…* (you should). Strongest: *Tienes que…* (you must). And completely impersonal: *Hay que…* (one must) – this way, you give advice without addressing anyone directly.",
  "Am Wochenende fahren wir aufs Land.": "We're going to the countryside this weekend.",
  "Am Wochenende war ich in Valencia.": "On the weekend, I was in Valencia.",
  "Amerika ist förmlicher": "Latin America is more formal",
  "an deiner Stelle": "if I were you",
  "An deiner Stelle würde ich das vergessen. Niemand lacht.": "If I were you, I'd forget about that. No one laughs.",
  "An deiner Stelle würde ich es überlegen.": "If I were you, I'd think about it.",
  "An deiner Stelle würde ich ihn anrufen.": "If I were you, I'd call him.",
  "An deiner Stelle würde ich mit dem Chef reden.": "If I were you, I would talk to the boss.",
  "An deiner Stelle würde ich mit ihr reden.": "If I were you, I would talk to her.",
  "An dem Automaten nicht. Der nimmt Gebühren.": "Not from that ATM. It charges fees.",
  "an den Strand gehen": "to go to the beach",
  "An den Wind erinnern sich die Besucher am meisten. Er weht fast jeden Tag und ist so stark, dass die Bäume schief wachsen, immer in dieselbe Richtung.": "Visitors remember the wind most. It blows almost every day and is so strong that trees grow crooked, always in the same direction.",
  "An der Ecke verkaufen sie Obst.": "They sell fruit on the corner.",
  "An der Kasse sind viele Leute.": "There are a lot of people at the checkout.",
  "An der Küste": "By the Coast",
  "An Infinitiv und Befehl hängt es hinten an": "Attached to infinitives and commands",
  "An Silvester essen wir zwölf Trauben.": "On New Year's Eve, we eat twelve grapes.",
  "An Silvester isst man in Spanien zwölf Weintrauben – eine pro Glockenschlag. Wer alle schafft, hat ein gutes Jahr.": "On New Year's Eve in Spain, people eat twelve grapes—one for each chime. If you finish them all, you'll have a good year.",
  "An spanischen Flughäfen wird kaum namentlich aufgerufen, und Gates wechseln kurzfristig. Wer sich auf Ansagen verlässt, steht am falschen Gate. Alle zwanzig Minuten auf die *pantalla* schauen ist die sichere Methode.": "At Spanish airports, names are rarely called, and gates can change last minute. Relying on announcements might leave you at the wrong gate. Checking the *pantalla* every twenty minutes is the safe way.",
  "An Weihnachten schon. Meine Schwester kommt im Mai.": "For Christmas, yes. My sister is coming in May.",
