  "Ana ___ comido ya.": "Ana has already eaten.",
  "Ana ___ muy cansada hoy.": "Ana ___ very tired today.",
  "Ana ___ por la mañana.": "Ana ___ in the morning.",
  "Ana ___ que trabajar el sábado.": "Ana ___ to work on Saturday.",
  "Ana ___ una carta a su madre.": "Ana ___ a letter to her mother.",
  "Ana conoce muy bien Barcelona": "Ana knows Barcelona very well.",
  "Ana dijo que ___ cansada.": "Ana said she ___ tired.",
  "Ana duscht morgens.": "Ana showers in the morning.",
  "Ana es ___ alta como su madre.": "Ana is ___ tall as her mother.",
  "Ana es más alta como su hermana.": "Ana is taller than her sister.",
  "Ana está ___ un libro muy bueno.": "Ana is ___ a very good book.",
  "Ana García López heißt so, weil ihr Vater García und ihre Mutter López heißt. Bei der Heirat ändert sich nichts – Namensänderungen kennt Spanien nicht. Angesprochen wird sie mit dem ersten: *señora García*.": "Ana García López is named this way because her father's last name is García and her mother's is López. In Spain, names don't change upon marriage. She's addressed by the first: *señora García*.",
  "Ana gebe ich meine Nummer.": "To Ana I give my number.",
  "Ana ha hacido la comida.": "Ana has made the food.",
