  "Anas Küche, Samstagvormittag. Ana und Carmen teilen sich die Wohnung.": "Ana's kitchen, Saturday morning. Ana and Carmen share the apartment.",
  "anbei": "attached",
  "Anbei mein Lebenslauf.": "I am attaching my resume.",
  "Andalusien": "Andalusia",
  "Andando, porque está muy cerca": "On foot, because it's very close",
  "ändern": "to change",
  "andernfalls": "otherwise",
  "Andernfalls würde ich die Stelle wechseln.": "Otherwise, I'd change jobs.",
  "Anders als im Deutschen steht das Adjektiv fast immer HINTER dem Wort: „un coche rojo“, nicht „un rojo coche“.": "Unlike in English, adjectives almost always come AFTER the noun: 'un coche rojo', not 'a red car'.",
  "Anders als im Deutschen wandert die Verneinung nach vorn: *No hablo francés* – wörtlich „nicht spreche ich Französisch“. Zwischen *no* und das Verb passt nichts außer einem Pronomen.": "Unlike in English, the negation comes first: *No hablo francés* – literally \"not I speak French.\" Nothing fits between *no* and the verb except a pronoun.",
  "Anders als im Deutschen wird das Verb nicht ans Ende geschoben und meist kein Komma gesetzt: *El bar que está en la esquina es buenísimo.* Der Satz läuft einfach weiter.": "Unlike in English, the verb doesn't get pushed to the end, and usually, no comma is needed: *El bar que está en la esquina es buenísimo.* The sentence just flows on.",
  "Anders als im Deutschen zählt man normal: *el uno de enero*, *el quince de mayo*, *el treinta y uno de diciembre*. Kein „erster“, kein Punkt hinter der Zahl. Nur der Monatsname wird kleingeschrieben.": "Unlike in English, you count normally in Spanish: *el uno de enero*, *el quince de mayo*, *el treinta y uno de diciembre*. No \"first,\" no period after the number. Only the month name is lowercase.",
  "Anders als im Englischen ist die Verlaufsform im Spanischen die Ausnahme – sie betont, dass etwas gerade in diesem Moment läuft.": "Unlike in English, the progressive form in Spanish is the exception – it emphasizes that something is happening right at this moment.",
  "Anders als in manchen Ländern packt man in Spanien direkt aus, vor den Augen des Schenkenden. Dazu gehört ein hörbares *¡Qué bonito!* oder *¡No tenías que molestarte!* – „das wäre doch nicht nötig gewesen“.": "Unlike in some countries, in Spain you open gifts right away, in front of the giver. It's customary to say something like *¡Qué bonito!* or *¡No tenías que molestarte!* – \"you shouldn't have gone to the trouble.\"",
  "Anerkennung aussprechen": "Expressing appreciation",
  "anfangs fiel es mir schwer": "at first it was hard for me",
  "Anfangs fielen mir die Zeiten schwer.": "At first, the schedule was hard for me.",
  "Angst haben": "to be afraid",
  "AnioNDuHu6M": "AnioNDuHu6M",
  "ankommen": "to arrive",
  "Ankommen in der Sprache – ohne Grammatik, nur Sprechen": "Dive In: Speak Without Grammar",
  "Anoche cenamos en un restaurante": "Last night, we had dinner at a restaurant.",
  "anprobieren": "to try on",
  "Anrede und Höflichkeit im Vergleich": "Addressing and politeness compared",
  "Anrede: *Querida Ana*. Ort und Lage: *Te escribo desde…* Höhepunkte: *Lo mejor ha sido…, lo peor…* Schluss: *Un abrazo*. Damit steht jede Postkarte, jede Nachricht und jeder kurze Bericht.": "Greeting: *Querida Ana*. Place and situation: *Te escribo desde…* Highlights: *Lo mejor ha sido…, lo peor…* Closing: *Un abrazo*. This structure works for every postcard, message, and short report.",
  "anrufen": "to call",
  "Anrufen & schreiben": "Calling & texting",
  "Anrufen ist normal": "Calling is Normal",
  "Ansprechen, ohne zu verletzen": "Addressing Without Offending",
  "anstoßen": "toast",
