  "b und v klingen gleich": "b and v sound the same",
  "B1. Und übertreib nicht, das merkt man sofort.": "B1. And don't exaggerate, it's obvious right away.",
  "baden": "to bathe",
  "Bahnhof Atocha, Madrid. Tom und Lena wollen nach Valencia. Lena ist zu Besuch aus Deutschland.": "Atocha Station, Madrid. Tom and Lena want to go to Valencia. Lena is visiting from Germany.",
  "bald": "soon",
