  "bevor": "before",
  "Bewerben, verhandeln, telefonieren, präsentieren, Konflikte ansprechen, Feedback geben. Das ist die Stufe, auf der die Sprache aufhört, ein Hobby zu sein, und anfängt, etwas zu verändern.": "Applying, negotiating, making calls, presenting, addressing conflicts, giving feedback. This is the level where the language stops being a hobby and starts making a difference.",
