  "bis": "until",
  "Bis 29 steht alles zusammen: *veintiuno*, *veintidós*. Ab 30 kommt ein *y* dazwischen und alles wird getrennt: *treinta y uno*, *cuarenta y cinco*, *noventa y nueve*. Ein *treintaiuno* gibt es nicht.": "Up to 29, everything is written together: *veintiuno*, *veintidós*. From 30 onwards, you add a *y* and write separately: *treinta y uno*, *cuarenta y cinco*, *noventa y nueve*. There's no *treintaiuno*.",
  "Bis dahin alles normal.": "Everything normal until then.",
  "Bis in die frühen Morgenstunden": "Until the early morning hours.",
  "Bis jetzt hast du kurze Sätze gebaut. *porque*, *pero*, *cuando*, *aunque* und *así que* hängen sie aneinander: *No puedo ir porque tengo que trabajar, pero quizás el domingo sí.* Ein Satz statt drei – und du klingst sofort flüssiger.": "So far, you've built short sentences. *porque*, *pero*, *cuando*, *aunque*, and *así que* connect them: *No puedo ir porque tengo que trabajar, pero quizás el domingo sí.* One sentence instead of three – and you sound instantly more fluent.",
  "Bis Juni, glaube ich. Kommt auf die Arbeit an.": "Until June, I think. Depends on work.",
  "Bis Mitternacht, dann müssen alle gehen": "Until midnight, then everyone has to leave.",
  "Bis morgen, Ana.": "See you tomorrow, Ana.",
  "bis spät": "until late",
  "Bis spät. Hier amüsieren wir uns wirklich.": "Until late. We really enjoy ourselves here.",
  "bis später": "see you later",
  "Bis später. Und dein Kaffee … geht heute aufs Haus.": "See you later. And your coffee … is on the house today.",
  "Bis zur halben Stunde zählt man dazu: *las tres y diez*, *las tres y media*. Danach zieht man von der nächsten Stunde ab: *las cuatro menos veinte*, *las cuatro menos cuarto*. Für „um“ steht *a*: *a las ocho*.": "Up to half past, you add minutes: *las tres y diez*, *las tres y media*. After that, you subtract from the next hour: *las cuatro menos veinte*, *las cuatro menos cuarto*. For 'at' a specific time, use *a*: *a las ocho*.",
