  "Bürgerkrieg und Franco-Diktatur sind nicht Geschichte, sondern Familiengeschichte – Großeltern haben sie erlebt. Fragen sind erlaubt, aber Urteile besser nicht. Dasselbe gilt für die Unabhängigkeitsbewegungen in Katalonien und im Baskenland.": "The Civil War and Franco's dictatorship are not just history, but family history – grandparents lived through them. Questions are okay, but judgments are best avoided. The same goes for the independence movements in Catalonia and the Basque Country.",
