  "Das -ito macht alles freundlich": "The -ito makes everything friendly",
  "Das -ito verkleinert nicht nur: „un momentito“ dauert genauso lang wie ein Moment, klingt aber freundlicher.": "The -ito doesn't just make things smaller: \"un momentito\" lasts as long as a moment but sounds friendlier.",
  "Das -se wandert nach vorn und passt sich an: levantarse wird zu me levanto.": "The -se moves to the front and changes: levantarse becomes me levanto.",
  "Das „libro de reclamaciones“ – das Beschwerdebuch – muss jeder Betrieb in Spanien vorhalten. Allein die Bitte darum wirkt oft Wunder.": "The 'libro de reclamaciones' – the complaint book – must be available in every business in Spain. Just asking for it often works wonders.",
  "Das „menú del día“ – Vorspeise, Hauptgang, Nachtisch und Getränk für einen Festpreis – gibt es mittags fast überall.": "The \"menú del día\" – starter, main course, dessert, and drink for a set price – is available almost everywhere at lunchtime.",
  "Das *h* wird nie gesprochen: *hola* klingt wie „ola\". Das *j* dagegen klingt wie ein deutsches „ch\" in „Bach\": *Juan* = „Chuan\".": "The *h* is never pronounced: *hola* sounds like \"ola\". The *j*, however, sounds like the English \"h\" in \"hello\": *Juan* = \"Huan\".",
  "Das *j* ist immer ein Rachenlaut: *trabajo* klingt wie „trabacho“. Vor *e* und *i* klingt auch das *g* so: *gente* wird „chente“, *gitarra* dagegen mit *u* geschrieben – *guitarra* – damit es hart bleibt.": "The *j* is always a throat sound: *trabajo* sounds like \"trabacho.\" Before *e* and *i*, the *g* also sounds this way: *gente* becomes \"chente,\" but *guitarra* is spelled with a *u* – *guitarra* – to keep it hard.",
  "Das *se* sagt, dass die Handlung auf einen selbst zurückfällt. *Despierto a mi hijo* – ich wecke meinen Sohn. *Me despierto* – ich wache auf. *Lavo el coche* gegen *me lavo* funktioniert genauso.": "The *se* indicates that the action reflects back on oneself. *Despierto a mi hijo* – I wake my son. *Me despierto* – I wake up. *Lavo el coche* versus *me lavo* works the same way.",
  "Das Adjektiv kommt danach": "The Adjective Comes After",
