  "Das Alphabet & Aussprache": "The alphabet & pronunciation",
  "Das Alter steht mit *tener*, nicht mit *ser*: *Tengo treinta años.* *¿Cuántos años tienes?* Ein *Soy treinta* wäre so falsch wie „ich bin dreißig Jahre haben“ auf Deutsch. Und *años* darf nicht weggelassen werden.": "Age is expressed with *tener*, not *ser*: *Tengo treinta años.* *¿Cuántos años tienes?* Saying *Soy treinta* would be as incorrect as saying \"I am thirty years have\" in English. And you can't leave out *años*.",
