  "Das Deutsche kennt „dieser“ und „jener“, das Spanische drei Stufen: *este* (bei mir), *ese* (bei dir), *aquel* (weit von uns beiden). Im Laden zeigst du damit ohne Worte, was du meinst.": "English uses \"this\" and \"that,\" but Spanish has three levels: *este* (near me), *ese* (near you), *aquel* (far from both of us). In a store, you can point out what you mean without words.",
