  "Das Imperfekt": "The Imperfect Tense",
  "Das Imperfekt baut die Bühne: Wetter, Ort, Alter, Stimmung, was gerade lief. Das Indefinido bringt die Handlung: was dann geschah. *Era de noche y llovía* (Bühne). *Salí y cogí un taxi* (Handlung).": "The Imperfect sets the scene: weather, place, age, mood, what was happening. The Preterite brings the action: what happened next. *Era de noche y llovía* (setting). *Salí y cogí un taxi* (action).",
  "Das Imperfekt bilden": "Forming the imperfect tense",
