  "Das Indefinido ist die Erzählform Lateinamerikas: Was Spanier im Perfekt sagen, steht dort fast immer im Indefinido.": "The Indefinido is the storytelling tense in Latin America: What Spaniards say in the Perfect tense is often in the Indefinido there.",
  "Das Indefinido regelmäßig bilden": "Forming the Indefinido regularly",
