  "das ist dasselbe": "it's the same",
  "Das ist der Bruch, an dem alle Deutschen hängen bleiben: „sein\" heißt zweimal etwas anderes. ser für das Dauerhafte – Beruf, Herkunft, Wesen. estar für den Moment – Ort, Laune, Zustand. Diese Trennung begleitet dich bis Lektion 150.": "This is the tricky part: \"to be\" is split into two meanings. *Ser* is for permanent things – profession, origin, essence. *Estar* is for temporary states – location, mood, condition. This distinction will follow you until lesson 150.",
