  "Das Muster ist immer gleich: *Antes* plus Imperfekt, *ahora* plus Präsens. *Antes había un cine, ahora hay un supermercado.* *Antes íbamos andando, ahora vamos en coche.* Ein Satz, zwei Zeiten.": "The pattern is always the same: *Antes* with the imperfect, *ahora* with the present. *Antes había un cine, ahora hay un supermercado.* *Antes íbamos andando, ahora vamos en coche.* One sentence, two tenses.",
  "das Niveau": "the level",
