  "das Ñ": "the ñ",
  "Das ñ hat einen eigenen Platz im Alphabet – es entstand aus einem doppelten n im Mittelalter.": "The ñ has its own spot in the alphabet – it came from a double n in the Middle Ages.",
  "Das Ñ ist ein spanischer Buchstabe.": "The ñ is a Spanish letter.",
