  "das Paprikapulver": "the paprika",
  "Das Perfekt": "The present perfect tense",
  "Das Perfekt – *he hablado*, *has comido* – erzählt, was heute, diese Woche, in letzter Zeit passiert ist. haber steht immer direkt vor dem Partizip, ohne Zwischenwort. Acht Partizipien tanzen aus der Reihe: visto, hecho, dicho, puesto, vuelto, escrito, abierto, roto.": "The perfect tense – *he hablado*, *has comido* – tells what happened today, this week, recently. *Haber* always stands right before the participle, with no words in between. Eight participles break the rule: visto, hecho, dicho, puesto, vuelto, escrito, abierto, roto.",
  "Das Perfekt bilden": "Forming the present perfect",
  "Das Perfekt mit haber": "The present perfect with haber",
  "das Pferd": "the horse",
  "Das Plateau ist normal": "The plateau is normal",
  "Das Plusquamperfekt": "The Past Perfect",
  "Das Plusquamperfekt – *había llegado* – ist das, was noch vor dem Vergangenen lag. Zusammen mit der Verlaufsform *estaba comiendo* und der indirekten Rede *dijo que vendría* hast du jetzt jede Zeitstufe, die eine Geschichte braucht.": "The pluperfect – *había llegado* – is what happened before the past. Along with the continuous form *estaba comiendo* and indirect speech *dijo que vendría*, you now have every tense a story needs.",
  "Das Plusquamperfekt bilden": "Forming the past perfect",
  "Das Plusquamperfekt ist die einzige Vergangenheitsform, die im Spanischen genauso funktioniert wie im Deutschen – ein seltener Glücksfall.": "The past perfect is the only past tense that works the same in Spanish as it does in English—lucky break!",
