  "Das Pronomen steht VOR dem Verb: *Lo leo.* *La compro.* *Los veo.* Beim Verneinen kommt es zwischen *no* und Verb: *No lo entiendo.* Zwischen Pronomen und Verb passt nichts anderes.": "The pronoun goes BEFORE the verb: *Lo leo.* *La compro.* *Los veo.* When negating, it comes between *no* and the verb: *No lo entiendo.* Nothing else fits between the pronoun and the verb.",
