  "Das Spanische hat kein einzelnes Wort für „vermissen“: *Echo de menos a mi familia.* In Lateinamerika sagt man *extrañar*: *Extraño a mi familia.* Vor Personen steht wieder das *a*.": "Spanish doesn't have a single word for \"miss\": *Echo de menos a mi familia.* In Latin America, they say *extrañar*: *Extraño a mi familia.* Use *a* before people.",
