  "Das umgekehrte Fragezeichen am Anfang ist kein Schmuck: Weil Spanisch keine Umstellung im Satzbau braucht, sieht man erst daran, dass eine Frage kommt.": "The upside-down question mark at the start isn't decoration: Since Spanish doesn't need word order changes for questions, it shows you a question is coming.",
