  "Das Verb richtet sich nach dem Ding": "The verb matches the thing",
  "Das Verb richtet sich nach dem, was gefällt: *Me gusta el libro* (eines), *Me gustan los libros* (mehrere). Steht ein Verb dahinter, bleibt es immer *gusta*: *Me gusta bailar*, *Me gusta leer y escribir* – auch bei zweien.": "The verb agrees with what pleases: *Me gusta el libro* (one), *Me gustan los libros* (several). If a verb follows, it stays *gusta*: *Me gusta bailar*, *Me gusta leer y escribir* – even with two.",
