  "Das Wetter taugt in Spanien kaum als Gesprächsthema – Essen, Fußball und die eigene Familie schon.": "In Spain, weather isn't much of a topic – food, soccer, and family are.",
  "Das Wichtige ist nicht der Geschmack, sondern der Brauch. Eine Person bereitet den Mate zu und reicht ihn an die nächste weiter. Alle trinken aus demselben Gefäß, einer nach dem anderen.": "The important part isn't the taste, but the ritual. One person prepares the mate and passes it to the next. Everyone drinks from the same container, one after another.",
  "das Wochenende": "the weekend",
