  "das Wort": "the word",
  "Das Wort „chocolate\" ist eines der wenigen, die aus dem Nahuatl über das Spanische in fast jede Sprache der Welt gewandert sind – „Tomate\" und „Avocado\" auch.": "The word \"chocolate\" is one of the few that traveled from Nahuatl through Spanish into almost every language – \"tomato\" and \"avocado\" too.",
  "Das Wort „coger“ ist in Spanien harmlos und in Argentinien, Mexiko und Chile eine Obszönität – dort heißt es „tomar“.": "The word \"coger\" is harmless in Spain but obscene in Argentina, Mexico, and Chile – there, it's \"tomar.\"",
  "Das Wort „ojalá“ kommt aus dem Arabischen – „law šāʾ Allāh“, so Gott will. Achthundert Jahre maurische Geschichte in einem Alltagswort.": "The word \"ojalá\" comes from Arabic – \"law šāʾ Allāh\", meaning God willing. Eight hundred years of Moorish history in a single everyday word.",
