  "Das zählt auch. Hast du ihnen das Buch gegeben?": "That counts too. Did you give them the book?",
  "Das Zeichen des Weges ist ein gelber Pfeil. Er ist auf Bäume, Steine und Mauern gemalt. Solange du ihm folgst, verläufst du dich nicht.": "The path's symbol is a yellow arrow. It's painted on trees, stones, and walls. As long as you follow it, you won't get lost.",
