  "Dass so viele Redewendungen ums Essen kreisen, ist kein Zufall – in Spanien wird über Essen geredet, während man isst.": "It's no accident that so many idioms revolve around food – in Spain, people talk about food while eating.",
  "Dass wir an einem Tag um acht essen. An einem einzigen.": "That we have dinner at eight one day. Just one.",
  "Dasselbe *nos* und *se* wie bei *me levanto* bedeutet in der Mehrzahl „einander“: *Nos vemos* (wir sehen uns), *Se escriben* (sie schreiben einander). Nur die Mehrzahlformen können das – bei *me* geht es nicht.": "The same *nos* and *se* used in *me levanto* mean \"each other\" in the plural: *Nos vemos* (we see each other), *Se escriben* (they write to each other). Only the plural forms can do this – it doesn't work with *me*.",
