  "Dem Asador beim Feuer dreinzureden gilt als grobe Unhöflichkeit. Es gibt sogar ein Wort dafür, wenn jemand es doch tut: „opinólogo\" – Meinungskundler.": "Interrupting the grill master at the fire is considered very rude. There's even a word for someone who does it: \"opinólogo\" – opinion giver.",
