  "der": "the",
  "Der „albergue“ ist mehr als eine Jugendherberge – entlang des Jakobswegs ist er ein eigenes Netz mit eigenen Regeln.": "The 'albergue' is more than a youth hostel – along the Camino de Santiago, it's a unique network with its own rules.",
  "Der „paseo“ – der abendliche Spaziergang durch den Ort – ist in Spanien ein eigenes Hobby und oft der Anlass, Nachbarn zu treffen.": "The \"paseo\" – an evening stroll through town – is a hobby in Spain and often a chance to meet neighbors.",
  "der (Zug-)Bahnhof": "the (train) station",
  "Der *piso* ist die normale Etagenwohnung in Spanien. Ein *apartamento* ist kleiner, oft eine Ferienwohnung. *Casa* meint eigentlich das Haus – aber *voy a casa* heißt einfach „ich gehe nach Hause“, egal wo man wohnt.": "The *piso* is the standard apartment in Spain. An *apartamento* is smaller, often a vacation rental. *Casa* actually means house – but *voy a casa* simply means \"I'm going home,\" no matter where you live.",
