  "Der Befehl ist fast die er-Form": "The command is almost the he-form",
  "Der bejahte Befehl ist die *él*-Form: *¡Habla!* Der verneinte tauscht den Vokal: *¡No hables!* Bei *-er* und *-ir* umgekehrt: *¡Come!* wird zu *¡No comas!* Merkregel: Die Endungen kreuzen sich.": "The affirmative command uses the *él* form: *¡Habla!* The negative swaps the vowel: *¡No hables!* For *-er* and *-ir* verbs, it's the opposite: *¡Come!* becomes *¡No comas!* Remember: The endings cross over.",
