  "Der Brauch ist, nicht an einem einzigen Ort zu bleiben. Man geht in eine Bar, nimmt einen Pintxo und ein Getränk, und geht dann zur nächsten Bar. Das nennt man „ir de pintxos\".": "The custom is not to stay in one place. You go to a bar, have a pintxo and a drink, then move to the next bar. This is called \"ir de pintxos.\"",
