  "Der eleganteste Rat im Spanischen. Statt *deberías hacer esto* sagt man *Si yo fuera tú, lo haría así.* Es klingt nach Angebot statt nach Anweisung – und wird deshalb viel eher angenommen.": "The most elegant advice in Spanish. Instead of saying *you should do this*, you say *Si yo fuera tú, lo haría así.* It sounds like a suggestion rather than a command – and is therefore more likely to be accepted.",
