  "Der Indikativ berichtet, was ist: *Luis viene.* Der Subjuntivo hält etwas in der Schwebe: *Ojalá venga Luis.* Es ist nicht sicher, ich wünsche es mir nur. Diese Unterscheidung gibt es im Deutschen kaum – deshalb muss man sie neu lernen.": "The Indicative states what is: *Luis viene.* The Subjunctive keeps things uncertain: *Ojalá venga Luis.* It's not certain, it's just a wish. This distinction isn't common in English, so it's something new to learn.",
