  "Der Jakobsweg ist eine alte Route, die in der Stadt Santiago de Compostela im Nordwesten Spaniens endet. Viele Leute gehen ihn zu Fuß, manche mit dem Fahrrad.": "The Camino de Santiago is an ancient route ending in Santiago de Compostela in northwest Spain. Many walk it, some cycle.",
