  "Der Satz „cualquier tiempo pasado fue mejor“ – jede vergangene Zeit war besser – ist ein geflügeltes Wort und wird meist ironisch benutzt.": "The phrase \"cualquier tiempo pasado fue mejor\" – any past time was better – is a saying often used ironically.",
  "Der Satz „cuando tenga tiempo“ ist die höflichste Art, etwas auf unbestimmte Zeit zu verschieben.": "The phrase \"cuando tenga tiempo\" is the politest way to postpone something indefinitely.",
  "Der Satz „se lo doy“ hat drei Wörter und vier Bedeutungen – wer ihn beherrscht, klingt sofort fortgeschritten.": "The sentence \"se lo doy\" has three words and four meanings – mastering it makes you sound advanced.",
