  "Der Subjuntivo braucht einen Wechsel: ICH freue mich, dass DU kommst – *Me alegro de que vengas.* Ist es dieselbe Person, steht der Infinitiv: *Me alegro de venir.* Kein Wechsel, kein Subjuntivo.": "The subjunctive needs a change: I am happy that YOU are coming – *Me alegro de que vengas.* If it's the same person, use the infinitive: *Me alegro de venir.* No change, no subjunctive.",
