  "deutsch (m/w)": "German",
  "Deutsch *-tion* wird spanisch *-ción*: *Information → información*, *Nation → nación*. Deutsch *-tät* wird *-dad*: *Universität → universidad*, *Möglichkeit → posibilidad*. Beide Gruppen sind **immer weiblich**: *la información*, *la universidad*.": "English *-tion* becomes Spanish *-ción*: *Information → información*, *Nation → nación*. English *-ty* becomes *-dad*: *University → universidad*, *Possibility → posibilidad*. Both groups are **always feminine**: *la información*, *la universidad*.",
  "Deutsch- und Französischkenntnisse.": "Knowledge of German and French.",
  "Deutsche loben zurückhaltend und kritisieren offen – in Spanien ist es umgekehrt. *Enhorabuena* fällt vor allen, oft überschwänglich. Der Verbesserungsvorschlag kommt danach, allein, und beginnt mit dem, was gut war.": "English speakers often praise modestly and criticize openly – in Spain, it's the opposite. *Congratulations* is said in front of everyone, often enthusiastically. The suggestion for improvement comes later, in private, and starts with what was done well.",
