  "Die drei Verbgruppen -ar, -er und -ir decken alle spanischen Verben ab. Wer die neun Endungen kann, beugt jedes regelmäßige Verb.": "The three verb groups -ar, -er, and -ir cover all Spanish verbs. If you know the nine endings, you can conjugate any regular verb.",
