  "Die Endung -ísimo ist keine Übertreibung, sondern Alltagssprache: „buenísimo“ hört man häufiger als „muy bueno“.": "The ending -ísimo isn't an exaggeration, it's everyday language: you'll hear \"buenísimo\" more often than \"muy bueno\".",
  "Die Endung hängt am ganzen Infinitiv – für alle drei Verbgruppen gleich.": "The ending is added to the whole infinitive – the same for all three verb groups.",
  "Die Endung sagt schon, wer gemeint ist: *hablo* kann nur „ich spreche“ heißen. Deshalb sagt man *Hablo español*, nicht *Yo hablo español*. Das Pronomen kommt nur dazu, wenn man betont oder vergleicht.": "The ending already tells you who is speaking: *hablo* can only mean “I speak.” That's why you say *Hablo español*, not *Yo hablo español*. The pronoun is only added for emphasis or comparison.",
