  "Die Schokolade kommt aus Mexiko und Mittelamerika. Dort wurde sie schon lange getrunken, bevor die Europäer kamen, aber sie war ganz anders als die, die wir kennen.": "Chocolate comes from Mexico and Central America. It was consumed long before Europeans arrived, but it was very different from what we know.",
