  "Die Siesta": "The siesta",
  "Die Siesta ist kein Nickerchen für alle: In Städten arbeitet man durch, aber viele kleine Läden schließen zwischen 14 und 17 Uhr.": "The siesta isn't a nap for everyone: In cities, people work through, but many small shops close between 2 and 5 PM.",
  "Die Signalwörter erkennen": "Recognize the signal words",
  "die Silbe": "the syllable",
  "Die Sobremesa kann zehn Minuten oder zwei Stunden dauern. Niemand schaut auf die Uhr. Man trinkt einen Kaffee, manchmal einen Nachtisch, und redet über alles: über die Arbeit, die Familie, Fußball.": "The sobremesa can last ten minutes or two hours. No one checks the time. You sip coffee, maybe have dessert, and talk about everything: work, family, soccer.",
