  "Die spanische Tortilla ist kein Fladen, sondern ein dickes Omelett aus Kartoffeln und Ei – die Zwiebel darin ist ein landesweiter Streitpunkt.": "The Spanish tortilla isn't a flatbread, but a thick omelet with potatoes and eggs – onions in it are a nationwide debate.",
