  "Die Straßen füllen sich mit Farbe. Viele Leute schminken sich das Gesicht als Totenschädel und gehen zum Tanzen auf die Straße. Der Tod macht an diesem Tag keine Angst: Er gehört zum Leben.": "The streets fill with color. Many people paint their faces as skulls and dance in the streets. Death isn't scary today: it's part of life.",
