  "die Uhrzeit": "the time",
  "Die Uhrzeit steht mit *ser* – und richtet sich nach der Stunde: *Es la una* (eine Stunde), aber *Son las dos*, *Son las siete*. Die *la* und *las* beziehen sich auf *hora* und *horas*, deshalb weiblich.": "Time is expressed with *ser* – and it depends on the hour: *Es la una* (one o'clock), but *Son las dos*, *Son las siete*. The *la* and *las* refer to *hora* and *horas*, which is why they are feminine.",
  "Die umgedrehten Zeichen": "The inverted symbols",
  "die Umkleide": "the fitting room",
  "Die Umkleide ist hinten.": "The fitting room is at the back.",
  "die Universität": "the university",
  "Die unregelmäßigen Formen im Indefinido": "The irregular forms in the Indefinido tense",
  "die Untertitel": "the subtitles",
  "Die ursprüngliche enthält keine Meeresfrüchte. Es war Essen vom Feld, mit Hühnchen, Kaninchen, grünen Bohnen und Reis. Die Meeresfrüchte kamen später dazu, an der Küste.": "The original had no seafood. It was a field meal with chicken, rabbit, green beans, and rice. Seafood was added later, on the coast.",
  "Die valencianische Original-Paella enthält Kaninchen, Huhn und grüne Bohnen – keine Meeresfrüchte. Die Version mit Garnelen heißt *paella de marisco*. Chorizo darin gilt in Valencia als Sakrileg, und man wird es dir sagen.": "The original Valencian paella contains rabbit, chicken, and green beans – no seafood. The version with shrimp is called *paella de marisco*. Adding chorizo is considered sacrilege in Valencia, and they'll let you know.",
  "Die Verben, die man einzeln lernt": "Verbs to Learn Individually",
  "Die Verbendung verrät schon, wer gemeint ist: *hablo* kann nur „ich spreche“ heißen. Deshalb sagt man einfach *Hablo español* – nicht *Yo hablo español*. Das Pronomen setzt man nur, wenn man betont: *Yo soy de Alemania, ¿y tú?*": "The verb ending already tells you who is meant: *hablo* can only mean “I speak.” So you just say *Hablo español* – not *Yo hablo español*. You only use the pronoun for emphasis: *Yo soy de Alemania, ¿y tú?*",
  "Die Vergangenheit kommt schon von selbst.": "The past comes naturally to me now.",
  "Die Vergangenheit vor der Vergangenheit": "Past Before the Past",
  "Die Verkleinerungsform bilden": "Forming the diminutive",
  "Die Verlaufsform bilden": "Forming the progressive",
