  "Die Wache ist zwei Straßen weiter.": "The police station is two blocks away.",
  "Die Wände sind weiß.": "The walls are white.",
  "Die Weihnachtslotterie, deren Zahlen von Kindern gesungen werden.": "The Christmas lottery, with numbers sung by children.",
  "die Weintraube": "the grape",
  "die Welle": "the wave",
  "Die Wendung „se me cayó“ verlagert die Schuld aufs Objekt – wörtlich: „es fiel mir“. Spanisch hat für Missgeschicke eine eigene Ausrede eingebaut.": "The phrase “se me cayó” shifts blame to the object – literally: “it fell from me”. Spanish has a built-in excuse for mishaps.",
  "Die Wendungen dieses Moduls funktionieren von Mexiko bis Argentinien. Unterschiede gibt es beim Wortschatz – *coger* wird zu *tomar*, *el móvil* zu *el celular* –, aber die Struktur bleibt.": "The phrases in this module work from Mexico to Argentina. There are vocabulary differences – *coger* becomes *tomar*, *el móvil* becomes *el celular* – but the structure stays the same.",
  "Die Wendungen mit dar und hacer nutzen": "Use phrases with dar and hacer",
