  "Die Zahlen werden nicht vorgelesen, sondern gesungen. Kinder einer Madrider Schule singen jede Zahl und jeden Gewinn laut vor. Das dauert mehrere Stunden.": "The numbers aren't read out, they're sung. Children from a Madrid school sing each number and prize aloud. It takes several hours.",
