  "Dienstag? Wir haben den Freitag.": "Tuesday? We have Friday.",
  "Diese Farbe steht dir gut.": "That color looks good on you.",
  "Diese Formen musst du vor allem *erkennen*: Schilder, Durchsagen und Fremde auf der Straße benutzen sie. Selbst sagen wirst du sie selten – da reicht *¿Puede decirme…?*": "You mainly need to *recognize* these forms: signs, announcements, and strangers on the street use them. You'll rarely need to say them yourself – *¿Puede decirme…?* is usually enough.",
  "Diese Formen tragen keinen Akzent": "These forms don't have an accent",
  "Diese Fotos sind von meiner Reise.": "These photos are from my trip.",
  "Diese Hose ist bequem.": "These pants are comfortable.",
  "Diese Jacke ist besser.": "This jacket is better.",
  "Diese kostet mehr als jene.": "This one costs more than that one.",
  "Diese Regel gilt für Spanien. In Lateinamerika nimmt man fast immer das Indefinido: *¿Ya comiste?* statt *¿Ya has comido?* Beides ist richtig – nur nicht gemischt innerhalb eines Gesprächs.": "This rule applies to Spain. In Latin America, the Preterite is almost always used: *¿Ya comiste?* instead of *¿Ya has comido?* Both are correct – just don't mix them within a conversation.",
  "Diese Reise war der Wendepunkt.": "That trip was the turning point.",
  "Diese Stelle interessiert mich.": "I'm interested in that position.",
  "Diese Suppe ist sehr lecker.": "This soup is really tasty.",
  "Diese Woche bin ich sehr beschäftigt.": "I'm really busy this week.",
  "Diese Woche habe ich schlecht geschlafen.": "I've slept badly this week.",
  "Diese Woche habe ich Spätschicht.": "This week I have the afternoon shift.",
  "Diese Woche hatte ich viel Arbeit.": "This week I had a lot of work.",
  "Diese Woche machte ich Überstunden.": "I worked overtime this week.",
  "Diese Woche werde ich nicht können.": "I won't be able to go this week.",
  "Diese Wohnung kostet ein Vermögen.": "That apartment costs a fortune.",
  "Dieselbe Handlung kann in beiden Formen stehen und bedeutet dann etwas anderes: „supe“ heißt ich erfuhr, „sabía“ heißt ich wusste.": "The same action can be in both tenses and mean different things: \"supe\" means I found out, \"sabía\" means I knew.",
  "Dieselbe Person: *para* plus Infinitiv – *Vengo para hablar contigo* (ich komme, ich rede). Zwei Personen: *para que* plus Subjuntivo – *Te lo doy para que lo leas* (ich gebe, du liest). Dieselbe Regel wie bei den Gefühlsverben.": "Same person: *para* plus infinitive – *Vengo para hablar contigo* (I come, I talk). Two people: *para que* plus Subjunctive – *Te lo doy para que lo leas* (I give, you read). Same rule as with emotion verbs.",
  "Dieselbe Regel für sechs Wörter": "Same rule for six words",
  "Dieselben Wörter, umgekehrt gemeint": "Same words, opposite meaning",
  "Diesen Tag vergesse ich nie.": "I'll never forget that day.",
