  "Donnerstag kann ich nicht, ich habe einen Termin.": "I can't on Thursday, I have an appointment.",
  "Donnerstags gehe ich zum Sprachaustausch.": "I go to a language exchange on Thursdays.",
  "Doña Pilar?": "Doña Pilar?",
  "Doppelt ist richtig": "Double is correct",
  "dormía": "was sleeping",
  "Dormir en un hotel y no en casa de la familia": "To sleep in a hotel and not at the family's house.",
  "Dort gebe ich nur Einzelunterricht. Ich würde gern mit Gruppen arbeiten.": "There, I only give private lessons. I'd like to work with groups.",
  "Dort heißt das Auto carro.": "There, a car is called carro.",
  "Dort sagt man manejar.": "There, they say manejar.",
  "Dort wird noch häufiger verkleinert – *ahorita* (gleich), *tantito* (ein bisschen), *cerquita* (ganz nah). In Mexiko kann *ahorita* alles zwischen sofort und heute Abend bedeuten.": "Diminutives are even more common there – *ahorita* (soon), *tantito* (a little bit), *cerquita* (very close). In Mexico, *ahorita* can mean anything from right now to later today.",
  "Drehen wir eine Runde?": "Shall we go for a walk?",
  "drei": "three",
  "Drei Arten, etwas zu verbieten": "Three ways to prohibit something",
  "Drei Aufgaben": "Three uses",
  "Drei Bausteine für jeden Vergleich": "Three building blocks for every comparison",
  "Drei Bauweisen": "Three ways to express it",
  "Drei Eier und eine halbe Zwiebel": "Three eggs and half an onion.",
  "Drei Entfernungen statt zwei": "Three distances instead of two",
  "Drei Entfernungen: hier, da und dort.": "Three distances: here, there, and over there.",
  "Drei Größen": "Three sizes",
  "Drei Marker genügen": "Three Markers are Enough",
  "Drei mögliche Folgen": "Three possible outcomes",
  "Drei Sätze lösen fast alles: *Tienes razón* (du hast recht), *No era mi intención* (das wollte ich nicht) und *¿Lo olvidamos?* (vergessen wir es?). Sie geben nach, ohne dass jemand das Gesicht verliert.": "Three phrases resolve almost anything: *Tienes razón* (you're right), *No era mi intención* (I didn't mean to), and *¿Lo olvidamos?* (shall we forget it?). They let you give in without anyone losing face.",
  "Drei Stärken der Entschuldigung": "Three strengths of an apology",
