  "Drei Stufen von Nachdruck": "Three levels of emphasis",
  "Drei Teile, und du kannst die Zukunft": "Three parts, and you can talk about the future",
  "Drei Temperaturen": "Three Levels of Formality",
  "Drei Verben tragen jede Wegbeschreibung": "Three verbs guide every direction",
