  "Drei Verben, drei Bereiche": "Three verbs, three areas",
  "Dreieinhalb, ja. An einer kleinen Schule im Viertel.": "Three and a half, yes. At a small school in the neighborhood.",
  "Dreikönigstag": "Epiphany",
  "dreißig": "thirty",
  "dringend": "urgent",
  "du": "you",
  "du (Río de la Plata)": "you",
  "Du ähnelst deiner Mutter.": "You look like your mother.",
  "du aßest": "you ate",
  "Du benutzt „era“, „había“, „iba“. Klingt natürlich.": "You use \"era,\" \"había,\" \"iba.\" Sounds natural.",
  "Du benutzt „sé“ und „conozco“. Was ist der Unterschied?": "You use \"sé\" and \"conozco.\" What's the difference?",
  "Du benutzt das Futur für die Gegenwart.": "You're using the future tense for the present.",
  "Du beschreibst deinen Tag (*me levanto, desayuno, salgo*), deine Wohnung (*hay, está*), deine Vorlieben (*me gusta*), was du kannst und musst (*puedo, tengo que*) und was du vorhast (*voy a*). Damit führst du ein einfaches Gespräch über den ganzen Alltag.": "You describe your day (*me levanto, desayuno, salgo*), your home (*hay, está*), your likes (*me gusta*), what you can and must do (*puedo, tengo que*), and your plans (*voy a*). This lets you have a simple conversation about everyday life.",
