  "du könntest": "you could",
  "du magst": "you like",
  "Du musst dich nicht entscheiden. Alle verstehen beide Varianten – ein Spanier weiß, was *celular* ist, ein Mexikaner kennt *móvil*. Nur bei *coger* lohnt es sich, die sichere Form zu nehmen.": "You don't have to decide. Everyone understands both versions – a Spaniard knows what *celular* is, a Mexican knows *móvil*. Only with *coger* is it worth using the safer form.",
  "Du musst in Sol umsteigen.": "You have to transfer at Sol.",
  "Du oder Sie, wie du magst.": "You or usted, whatever you prefer.",
  "Du oder Sie?": "You or You?",
  "Du sagst „acabes\", nicht „acabas\".": "You say \"acabes,\" not \"acabas.\"",
  "Du sagst „apruebes\", nicht „apruebas\".": "You say \"apruebes,\" not \"apruebas.\"",
  "Du sagst „baratísimo“. Ist das nicht übertrieben?": "You say \"baratísimo.\" Isn't that an exaggeration?",
  "Du sagst „bici roja“, nicht „roja bici“. Sehr gut.": "You say 'bici roja', not 'roja bici'. Very good.",
  "Du sagst „corta“, nicht „cortas“. Ist das ein Befehl?": "You say \"corta,\" not \"cortas.\" Is that a command?",
  "Du sagst „es rubia“, aber „lleva gafas“. Warum unterschiedlich?": "You say \"es rubia,\" but \"lleva gafas.\" Why different?",
  "Du sagst „estaba“ und dann „habló“. Perfekt.": "You say \"estaba\" and then \"habló\". Perfect.",
  "Du sagst „hablé“, nicht „he hablado“. Warum?": "You say \"hablé,\" not \"he hablado.\" Why?",
  "Du sagst „he hablado“, nicht „hablé“. Warum?": "You say \"he hablado,\" not \"hablé.\" Why?",
  "Du sagst „me duele la garganta“, nicht „mi garganta“.": "You say \"me duele la garganta,\" not \"mi garganta.\"",
  "Du sagst „me encantan“ mit N. Wegen der Konzerte?": "You say \"me encantan\" with an N because of the concerts?",
  "Du sagst „por el cine“ und vorhin „para ti“. Was ist die Regel?": "You said \"por el cine\" and earlier \"para ti\". What's the rule?",
  "Du sagst „un poco serio“. Ist das Kritik?": "You say \"un poco serio.\" Is that criticism?",
  "Du schreibst „entschuldige das Nachhaken\" und fertig.": "You write \"sorry for following up\" and that's it.",
  "Du siehst heute sehr hübsch aus.": "You look very pretty today.",
  "Du siehst heute sehr schick aus.": "You look very elegant today.",
  "du siehst ja": "you see",
  "Du siehst ja, viel Arbeit.": "You see, lots of work.",
  "du solltest": "you should",
  "Du solltest dich mehr ausruhen.": "You should rest more.",
  "Du solltest mehr sprechen, auch wenn du Fehler machst.": "You should speak more, even if you make mistakes.",
  "Du solltest mit ihr sprechen.": "You should talk to her.",
