  "Du sprichst noch nicht lange Spanisch, oder?": "You haven't been speaking Spanish for long, have you?",
  "Du sprichst sehr gut Spanisch.": "You speak Spanish very well.",
  "Du sprichst sehr schnell.": "You speak very fast.",
  "Du überquerst den Platz. Er ist neben der großen Bar.": "Cross the square. It's next to the big bar.",
  "Du überquerst die Straße und schon bist du da.": "Cross the street and you're there.",
