  "Ein Kilo Tomaten, bitte.": "A kilo of tomatoes, please.",
  "ein Kinderspiel sein": "to be a piece of cake",
  "Ein Kinderspiel. Obwohl ich vorher gezittert habe.": "A piece of cake. Even though I was nervous before.",
  "Ein Konfliktgespräch ohne Ergebnis kommt in zwei Wochen wieder. *De cara al futuro, ¿quedamos en que me avisas antes?* Danach kurz *sin rencor* – so ist die Sache erledigt und die Beziehung intakt.": "A conflict discussion without a resolution will resurface in two weeks. *Looking ahead, can we agree that you'll let me know beforehand?* Then briefly say *no hard feelings* – this resolves the issue and keeps the relationship intact.",
  "Ein Korn, das dort wächst, wo sonst fast nichts mehr wächst.": "A grain that grows where almost nothing else can.",
  "Ein Land, das keins ist": "A country that's not just one",
  "Ein Leben erzählen": "Telling a life story",
  "Ein Lehrer muss geduldig sein.": "A teacher has to be patient.",
  "Ein Maisfladen, über den zwei Länder sich freundschaftlich streiten.": "A corn cake that two countries have a friendly rivalry over.",
  "Ein Menü bestellen": "Ordering a menu",
  "Ein Missgeschick": "A mishap",
  "Ein Missverständnis klären": "How to clear up a misunderstanding",
  "ein Momentchen": "a tiny moment",
  "Ein nacktes *No puedo* klingt hart. Üblich ist: *Es que no puedo, lo siento.* Oder mit Aussicht: *Hoy no puedo, pero quizás el domingo.* Das *es que* ist die spanische Art, eine Erklärung anzukündigen.": "A plain *No puedo* sounds blunt. It's common to say: *Es que no puedo, lo siento.* Or offer an alternative: *Hoy no puedo, pero quizás el domingo.* The phrase *es que* is the Spanish way to introduce an explanation.",
  "Ein nacktes *No* wirkt hart. Üblicher sind: *No estoy del todo de acuerdo* (nicht ganz), *Bueno, depende* (kommt darauf an), *Sí, pero…* Wer widerspricht, fängt fast immer mit einer Zustimmung an.": "A plain *No* can sound harsh. More common are: *No estoy del todo de acuerdo* (not entirely), *Bueno, depende* (well, it depends), *Sí, pero…* When disagreeing, people often start with some agreement.",
  "Ein paar Adjektive stehen vorn und bedeuten dann etwas anderes: *un amigo viejo* ist ein alter Mann, *un viejo amigo* ein langjähriger Freund. *Un coche nuevo* ist fabrikneu, *un nuevo coche* nur neu für dich.": "Some adjectives change meaning based on position: *un amigo viejo* is an old man, *un viejo amigo* is a long-time friend. *Un coche nuevo* is brand new, *un nuevo coche* is just new to you.",
  "Ein Park, Sonntagnachmittag. Ana erzählt Luis von einem missglückten Abend.": "A park, Sunday afternoon. Ana tells Luis about an evening gone wrong.",
  "Ein Problem melden": "Reporting a problem",
