  "Ein wichtiges Detail: Vor dem Kochen muss man sie gut waschen. Die Körner haben außen eine bittere Schicht, die die Pflanze vor Vögeln schützt.": "An important detail: before cooking, it must be washed well. The grains have a bitter coating that protects the plant from birds.",
