  "Eine Nachricht schreiben": "Write a message",
  "Eine Nummer für Polizei, Feuerwehr und Rettung – in ganz Europa. Sie funktioniert ohne Guthaben, ohne SIM-Karte und wird in Spanien meist auch auf Englisch bedient. Mehr Nummern muss man sich nicht merken.": "One number for police, fire, and rescue across Europe. It works without credit, without a SIM card, and in Spain, it's often available in English. No need to remember more numbers.",
