  "Eine Verabredung „a las nueve“ heißt in Spanien selten Punkt neun – zehn bis fünfzehn Minuten später gelten als normal.": "A meeting at 'nine o'clock' in Spain rarely means exactly nine – being ten to fifteen minutes late is normal.",
