  "Einstieg: *Resulta que…* Verlauf: *Al principio… luego… de repente…* Wende: *Total que…* Schluss: *Al final… y ya está.* Wer diese vier Gerüstteile benutzt, klingt sofort wie jemand, der erzählen kann.": "Beginning: *Resulta que…* Progression: *Al principio… luego… de repente…* Twist: *Total que…* Ending: *Al final… y ya está.* Using these four parts makes you sound like a natural storyteller.",
