  "en und a richtig einsetzen": "Using en and a correctly",
  "Endet das Wort auf *-o* oder *-a*, tauscht man den Vokal: *momento → momentito*, *casa → casita*. Endet es auf *-e*, *-n* oder *-r*, kommt *-cito*: *coche → cochecito*, *joven → jovencito*, *mujer → mujercita*.": "If a word ends in *-o* or *-a*, swap the vowel: *momento → momentito*, *casa → casita*. If it ends in *-e*, *-n*, or *-r*, add *-cito*: *coche → cochecito*, *joven → jovencito*, *mujer → mujercita*.",
  "Endet ein Wort auf *-o*, ist es meist männlich (*el libro*); auf *-a* meist weiblich (*la mesa*). Auch *-ción*, *-dad* und *-tad* sind immer weiblich: *la ciudad*. Wörter auf *-e* oder Konsonant muss man einzeln lernen.": "If a word ends in *-o*, it's usually masculine (*el libro*); if it ends in *-a*, it's usually feminine (*la mesa*). Also, *-ción*, *-dad*, and *-tad* are always feminine: *la ciudad*. Words ending in *-e* or a consonant need to be learned individually.",
  "Endet ein Wort auf *Vokal*, *n* oder *s*, liegt die Betonung auf der vorletzten Silbe: *casa*, *examen*, *gracias*. Endet es auf einen anderen Konsonanten, auf der letzten: *hablar*, *feliz*, *ciudad*.": "If a word ends in a *vowel*, *n*, or *s*, the stress is on the second-to-last syllable: *casa*, *examen*, *gracias*. If it ends in any other consonant, it's on the last: *hablar*, *feliz*, *ciudad*.",
  "Endet ein Wort auf einen Vokal, hängst du *-s* an: *amigo → amigos*, *flor* dagegen endet auf Konsonant und bekommt *-es*: *flores*. Der Artikel wandert mit: *el → los*, *la → las*.": "If a word ends in a vowel, add *-s*: *amigo → amigos*, but *flor* ends in a consonant and gets *-es*: *flores*. The article changes too: *el → los*, *la → las*.",
  "Endlich einmal wie im Deutschen": "Finally, like in English",
