  "Entlang des *Camino de Santiago* gibt es ein dichtes Netz an *albergues* – oft ohne Reservierung, nach dem Prinzip „wer zuerst kommt“. Fußgänger haben Vorrang vor Radfahrern, und man bleibt nur eine Nacht.": "Along the *Camino de Santiago*, there's a dense network of *albergues* – often no reservation needed, first-come, first-served. Walkers have priority over cyclists, and you stay only one night.",
