  "Er entstand im 18. Jahrhundert aus der Kultur der Roma in Andalusien. Im Norden Spaniens hat er keine Wurzeln – dort gibt es Dudelsäcke in Galicien und eigene Tänze im Baskenland. „Spanische Musik\" gibt es so wenig wie spanische Küche.": "It originated in the 18th century from the culture of the Roma in Andalusia. In northern Spain, it has no roots – there are bagpipes in Galicia and unique dances in the Basque Country. There's as little \"Spanish music\" as there is Spanish cuisine.",
