  "Er ist ein Freund von der Arbeit.": "He's a friend from work.",
  "Er ist eine Haltung. Alles Gewünschte, Bezweifelte, Bewertete steht darin: *ojalá venga*, *espero que salga bien*, *no creo que tengas razón*. *Creo que tienes razón* bleibt im Indikativ – erst der Zweifel schaltet um. Das ist die Grenze, an der Spanisch aufhört, einfach zu sein.": "It's an attitude. Everything wished for, doubted, evaluated is in it: *ojalá venga* (I hope he comes), *espero que salga bien* (I hope it goes well), *no creo que tengas razón* (I don't think you're right). *Creo que tienes razón* (I think you're right) stays in the indicative – only doubt switches it. This is where Spanish stops being simple.",
