  "ernst": "serious",
  "ernten, aufsammeln": "harvest, gather",
  "Erst Bedauern, dann Grund, dann Aussicht: *Me encantaría, pero es que tengo que trabajar. ¿Lo dejamos para otro día?* Ein nacktes *No puedo* wirkt in Spanien schroff – die drei Schritte gehören dazu.": "First express regret, then give a reason, then offer an alternative: *I'd love to, but I have to work. How about another day?* A plain *I can't* can sound abrupt in Spain – the three steps are part of the etiquette.",
  "Erst die Person (me, te, le), dann die Sache (lo, la, los, las) – und wenn beide zusammentreffen, wird le zu se: *se lo doy*. Das ist die kniffligste Stelle des Moduls und die, an der man Muttersprachler am schnellsten beeindruckt.": "First the person (me, te, le), then the thing (lo, la, los, las) – and when both meet, le becomes se: *se lo doy*. This is the trickiest part of the module and the one where you can impress native speakers the fastest.",
  "Erst die Person, dann die Sache – und vor lo, la, los, las wird le zu se.": "First the person, then the thing – and before lo, la, los, las, le changes to se.",
  "Erst die Stimme, dann die Gitarre – der Tanz kam zuletzt dazu.": "First the voice, then the guitar – the dance was added last.",
  "Erst mal ja, aber es ist noch offen.": "For now, yes, but it's still undecided.",
  "Erst mal ja, aber nicht sicher.": "In principle, yes, but not for sure.",
  "Erst nach halb wird abgezogen": "After half past, you subtract from the next hour",
  "Erst sachlich: *La ducha no funciona.* Dann bitten: *¿Podría arreglarlo?* Dann nachdrücklich: *Llevo dos días esperando.* Zuletzt: *¿Me trae el libro de reclamaciones?* Die letzte Stufe braucht man selten – aber sie wirkt.": "First, straightforward: *La ducha no funciona.* Then, request: *¿Podría arreglarlo?* Next, insist: *Llevo dos días esperando.* Finally: *¿Me trae el libro de reclamaciones?* The last step is rarely needed – but it works.",
  "Erst sagst du „hay“, dann „está“. Warum?": "First you say \"hay\", then \"está\". Why?",
  "Erst was es gibt, dann wo es steht": "First what it is, then where it is",
  "Erst wem, dann was": "First to whom, then what",
  "Erste Schritte": "Getting Started",
  "erstens": "first of all",
  "Erstens die Ergebnisse.": "First of all, the results.",
  "Erstens: Warum ich schreibe (*En respuesta a su anuncio…*). Zweitens: Was ich mitbringe. Drittens: Warum diese Firma. Viertens: Verfügbarkeit und Gruß. Mehr als eine Seite liest niemand.": "First: Why I'm writing (*En respuesta a su anuncio…*). Second: What I bring. Third: Why this company. Fourth: Availability and closing. No one reads more than one page.",
