  "es gibt": "there is/are",
  "Es gibt drei große Städte.": "There are three big cities.",
  "Es gibt eine Bank in dieser Straße.": "There's a bank on this street.",
  "Es gibt eine Bar mit der besten Tortilla, die ich je probiert habe.": "There's a bar with the best tortilla I've ever tried.",
  "Es gibt eine Möglichkeit.": "There is a possibility.",
  "Es gibt eine patagonische Redensart für jemanden, der ständig jammert: Er habe „den Wind noch nicht kennengelernt\".": "There's a Patagonian saying for someone who constantly complains: They haven't \"met the wind yet.\"",
  "Es gibt eine Person, die sich um das Feuer und das Fleisch kümmert: den „asador\". Niemand sonst fasst den Grill an. Das ist eine Ehre, aber auch eine Verantwortung.": "There's one person in charge of the fire and the meat: the \"asador.\" No one else touches the grill. It's an honor, but also a responsibility.",
  "Es gibt eine Regel, die Besucher überrascht: Man darf die Bombilla nicht bewegen. Und wenn jemand beim Zurückgeben „gracias\" sagt, heißt das, dass er nichts mehr möchte.": "There's a rule that surprises visitors: You mustn't move the bombilla. And if someone says \"gracias\" when returning it, it means they don't want any more.",
  "Es gibt einen Satz, der in diesen Tagen oft wiederholt wird: „Wer es erlebt, hat auch etwas davon.\" Anders gesagt: Zuschauen reicht nicht, man muss mitmachen.": "There's a saying often repeated during these days: \"Those who experience it, benefit from it.\" In other words: Watching isn't enough, you have to join in.",
  "Es gibt einen um zehn vor zwölf, aber der ist ausgebucht.": "There's one at ten to twelve, but it's fully booked.",
  "Es gibt kein Problem.": "There's no problem.",
  "es gibt kein richtiges Spanisch": "there's no correct Spanish",
  "Es gibt kein richtiges Spanisch, es gibt mehrere.": "There's no correct Spanish, there are several.",
  "es gibt nicht die eine Art": "there's no single way",
  "Es gibt nicht die eine Art, es zu tun.": "There's not just one way to do it.",
  "Es gibt oder es ist": "There is or it is",
  "Es gibt Regeln. Die Tomaten müssen zerdrückt sein, bevor man sie wirft, damit sie nicht wehtun. Und wenn das Zeichen zum Schluss ertönt, wirft niemand mehr etwas.": "There are rules. Tomatoes must be squished before throwing so they don't hurt. And when the signal to stop sounds, no one throws anything anymore.",
  "Es gibt riesige Schildkröten, Leguane, die im Meer schwimmen, und Vögel, die man an keinem anderen Ort der Welt findet.": "There are giant tortoises, iguanas that swim in the sea, and birds you won't find anywhere else in the world.",
  "Es gibt Umzüge mit Musik, Kostümen und Tiermasken. Jede Gruppe tanzt ihren eigenen Rhythmus, und viele kommen aus kleinen Dörfern der Region.": "There are parades with music, costumes, and animal masks. Each group dances to its own rhythm, and many come from small villages in the region.",
  "Es gibt viel Regionalstolz.": "There's a lot of regional pride.",
  "Es gibt Wörter, die nur dort benutzt werden. Den Bus nennen sie „guagua\" und das Popcorn „cotufas\". Ein Spanier vom Festland versteht das nicht immer.": "There are words used only there. They call the bus \"guagua\" and popcorn \"cotufas.\" A mainland Spaniard might not always understand this.",
  "Es gibt zwanzig Minuten Verspätung.": "There's a twenty-minute delay.",
  "Es gibt zwanzig Prozent Rabatt.": "There's a twenty percent discount.",
  "Es gibt zwei, aber die andere ist sehr weit weg.": "There are two, but the other is very far away.",
  "Es ging genau in dem Moment aus. Null Prozent.": "It turned off at that exact moment. Zero percent.",
