  "es hat sich verspätet": "has been delayed",
  "Es heißt *si tengo tiempo*, nie *si tenga tiempo*. Diese Regel hat keine Ausnahme. Nach *si* steht Indikativ – Präsens für Mögliches, später kommt das Imperfekt des Subjuntivo für Unmögliches.": "It's *si tengo tiempo*, never *si tenga tiempo*. This rule has no exceptions. After *si*, use the indicative – present for possible situations, later the imperfect subjunctive for impossible ones.",
