  "Es ist nicht nur eine Redewendung. Es ist eine Art, die Dinge zu sehen: Es lohnt sich nicht, sich um das zu sorgen, was man nicht ändern kann.": "It's not just a phrase. It's a way of seeing things: It's not worth worrying about what you can't change.",
