  "Es ist wichtig, dass du früh ankommst.": "It's important that you arrive early.",
  "Es ist wichtig, sofort mit den grundlegenden Wörtern zu beginnen, die man im Alltag häufig benötigt. Diese Auswahl hilft dir, dich in einfachen Situationen auf Spanisch zurechtzufinden und dich schnell verständigen zu können.": "It's important to start right away with basic words you often need in daily life. This selection helps you navigate simple situations in Spanish and communicate quickly.",
