  "Es kann sein, dass es morgen regnet.": "It might rain tomorrow.",
  "Es klingt freundlich und bedeutet oft: eher nicht. Wer verbindlich zusagen will, sagt *cuenta conmigo* oder *te confirmo el jueves*. Wer ein *ya veremos* für eine Zusage hält, wartet vergeblich.": "It sounds friendly but often means: probably not. To confirm, say *cuenta conmigo* or *te confirmo el jueves*. If you take *ya veremos* as a yes, you'll be waiting in vain.",
