  "es machte mir Angst": "it scared me",
  "Es markiert, was VOR dem Erzählten geschah: *Cuando llegué, ya había salido.* Erst ging er, dann kam ich. Ohne diese Form müsste man umständlich erklären, was zuerst war.": "It marks what happened BEFORE the story: *Cuando llegué, ya había salido.* He left first, then I arrived. Without this form, you'd have to explain awkwardly what happened first.",
