  "Es sieht leicht aus, ist es aber nicht. Die Glockenschläge gehen schnell und die Trauben haben Kerne. Fast immer bleibt jemand zurück und lacht am Ende mit vollem Mund.": "It looks easy, but it's not. The chimes are fast and the grapes have seeds. Almost always, someone falls behind and ends up laughing with a full mouth.",
