  "Fahrpläne und Ansagen nutzen die 24-Stunden-Zeit: „las diecinueve treinta“ statt „las siete y media“.": "Schedules and announcements use the 24-hour clock: \"las diecinueve treinta\" instead of \"las siete y media\".",
  "Fahrpläne zählen bis 24": "Schedules count up to 24",
  "Fahrt ihr mit dem Auto oder mit dem Zug?": "Are you going by car or train?",
  "falls": "in case",
  "Fällt ein Feiertag auf Dienstag oder Donnerstag, nimmt man den Tag dazwischen frei – das ist der *puente*, die Brücke. Bei zwei Feiertagen in einer Woche spricht man vom *acueducto*. Halb Spanien plant sein Jahr danach.": "If a holiday falls on a Tuesday or Thursday, people take the day in between off – that's the *puente*, the bridge. When there are two holidays in a week, it's called an *acueducto*. Half of Spain plans their year around this.",
  "Familie": "Family",
  "Familie und nahestehende Menschen": "Family and close people",
  "Fang mit der ich-Form an. Wie sagst du „hacer\"?": "Start with the 'I' form. How do you say \"hacer\"?",
  "Farben & Beschreiben": "Colors & Describing",
  "Farben und Eigenschaften nennen": "Naming colors and qualities",
  "Fast alles, bis fünf. Das ist die Siesta.": "Almost everything, until five. That's siesta time.",
  "Fast gleich – sie trennen sich nur in der wir- und ihr-Form.": "Almost the same – they only differ in the 'we' and 'you all' forms.",
  "Fast hätte ich den Zug verpasst.": "I almost missed the train.",
  "Fast immer gibt es einen Bereich, in dem gegessen wird. Es sind einfache Tische und sehr gutes Essen, und dort sitzen die, die arbeiten, und die, die einkaufen, beisammen.": "There's almost always an area for eating. Simple tables and very good food, where workers and shoppers sit together.",
  "Fast immer. Manchmal ändert es vorn den Sinn.": "Almost always. Sometimes it changes the meaning at the start.",
  "Fast nie. Außer bei „coger\".": "Almost never. Except with \"coger.\"",
  "Fast nie. Hier gilt die Anzeigetafel.": "Almost never. The display board is what counts here.",
  "Fast niemand kauft ein ganzes Los, weil es teuer ist. Die Leute teilen sich: im Büro, in der Kneipe im Viertel, unter Freunden. Deshalb gewinnt manchmal ein ganzes Dorf.": "Almost no one buys a whole ticket because it's expensive. People share: at the office, in the local bar, among friends. That's why sometimes a whole village wins.",
  "Fast täglich. Wir helfen uns mit der Sprache.": "Almost daily. We help each other with the language.",
  "Fast. Mit zwei R: perro. Mit einem R heißt es „aber“.": "Almost. With two R's: perro. With one R, it means 'but'.",
