  "Flamenco ist andalusisch": "Flamenco is Andalusian",
  "Flamenco ist keine spanische Nationalkultur, sondern andalusisch – im Baskenland tanzt man ihn so wenig wie in Hamburg.": "Flamenco isn't a national Spanish culture, but Andalusian – in the Basque Country, it's as rare as in Hamburg.",
  "fleißig": "hardworking",
  "Folgen benennen": "Identify consequences",
  "Formelle Briefe enden in Spanien mit „Atentamente“ – ein deutsches „Mit freundlichen Grüßen“ wörtlich zu übersetzen, wirkt hölzern.": "Formal letters in Spain end with \"Atentamente\" – directly translating \"Yours sincerely\" sounds awkward.",
  "Formelle Wendungen benutzen": "Using formal expressions",
  "Förmlicher wird es mit a fin de que": "More formal with a fin de que",
  "Fotografieren verboten": "no photos allowed",
  "Frag dich: WER oder WAS ist das? Dann *ser*. WO ist es oder WIE steht es gerade? Dann *estar*. *Ana es profesora* (was sie ist), *Ana está en clase* (wo sie ist), *Ana está cansada* (wie es ihr geht). Vergiss „dauerhaft gegen vorübergehend“ – *estar muerto* ist reichlich dauerhaft.": "Ask yourself: WHO or WHAT is it? Then use *ser*. WHERE is it or HOW is it doing right now? Then use *estar*. *Ana es profesora* (what she is), *Ana está en clase* (where she is), *Ana está cansada* (how she feels). Forget “permanent vs. temporary” – *estar muerto* is quite permanent.",
  "fragen": "to ask",
  "Fragen ganz ohne Fragewort": "Questions without question words",
  "Fragen indirekt wiedergeben": "Reporting questions indirectly",
  "Fragen ist erlaubt und erwünscht": "Questions are welcome",
  "Fragen ja. Von außen urteilen, besser nicht.": "Ask, yes. But judging from outside, better not.",
  "Fragen mit si oder Fragewort": "Questions with if or question word",
  "Fragen ohne Fragewort bilden": "Form questions without a question word",
  "Fragen Sie nach Herrn García.": "Ask for Mr. García.",
  "Fragen stellen": "Asking questions",
  "Fragen, die immer kommen": "Questions That Always Arise",
  "Fragen, wie es jemandem geht": "Ask how someone is doing",
  "Fragewörter tragen immer einen Akzent": "Question words always have an accent",
  "frei": "free",
  "Fremde auf der Straße siezt man in Spanien nur, wenn sie deutlich älter sind – unter jungen Leuten ist das Du selbstverständlich.": "In Spain, you only use formal 'usted' with strangers if they're clearly older – among young people, informal 'tú' is the norm.",
  "Fremde Automaten fragen: *¿Acepta la comisión de 3,50 €?* Wer *Sí* drückt, zahlt. Noch teurer ist die Frage *¿Desea el cambio en euros?* – dieser „Service“ kostet oft 5 % Aufschlag. Immer in der Landeswährung abrechnen.": "Foreign ATMs might ask: *¿Acepta la comisión de 3,50 €?* If you press *Sí*, you pay. Even more costly is the question *¿Desea el cambio en euros?* – this “service” often adds a 5% fee. Always settle in the local currency.",
  "Freude und Bedauern ausdrücken": "Expressing joy and regret",
  "Freunde & Bekannte": "Friends & Acquaintances",
  "Freundlich bleibt wirksamer": "Kindness is more effective",
  "Freundschaften in Spanien laufen über Nähe statt Termine: Man ruft an und kommt vorbei, statt drei Wochen vorher zu planen.": "Friendships in Spain are about closeness, not schedules: You call and drop by instead of planning weeks ahead.",
  "freut mich": "nice to meet you",
  "Freut mich, Carmen.": "Nice to meet you, Carmen.",
  "Freut mich, Tom. Wie schreibt man das? Mit zwei M?": "Nice to meet you, Tom. How do you spell that? With two M's?",
  "Freut mich. Ich komme aus Deutschland.": "Nice to meet you. I'm from Germany.",
  "frisch": "fresh",
  "Frisches kauft man in Spanien oft nicht im Supermarkt, sondern im „mercado“ – der Markthalle, die täglich geöffnet ist.": "In Spain, fresh produce is often bought at the \"mercado\" – a market hall open daily, not the supermarket.",
  "fröhlich": "happy",
  "früh": "early",
  "früher": "earlier",
  "Früher gab es hier ein Kino.": "There used to be a cinema here.",
  "Früher gab es kein Internet.": "There was no internet before.",
  "Früher gingen wir jeden Sonntag in den Park.": "We used to go to the park every Sunday.",
  "Früher lebten wir in einem kleinen Dorf.": "We used to live in a small village.",
  "Früher lernte ich hundert Wörter pro Woche.": "I used to learn a hundred words a week.",
  "Früher und heute nebeneinander": "Then and now side by side",
  "Früher und heute vergleichen": "Compare past and present",
