  "Fue andando hasta el bar para buscar a Carmen": "She walked to the bar to find Carmen.",
  "fui, tuve, hice, estuve, pude – diese Stämme tragen keinen Akzent am Ende.": "fui, tuve, hice, estuve, pude – these stems don't have an accent at the end.",
  "füllen": "to fill",
  "Fundamente": "Basics",
  "fünf": "five",
  "Fünf Fragen, die immer kommen": "Five questions that always come up",
  "Fünf sicher eingesetzte Wendungen wirken besser als zwanzig halb verstandene. Wer sie an der falschen Stelle einwirft, klingt wie ein Sprachkurs auf zwei Beinen. Im Zweifel: normal sprechen.": "Five well-used idioms are better than twenty half-understood ones. Using them in the wrong place makes you sound like a walking language course. When in doubt: speak normally.",
  "Fünf. Von acht bis eins. Aber am Wochenende habe ich frei.": "Five. From eight to one. But I have weekends off.",
  "fünfhundert": "five hundred",
  "Fünfhundert Gramm Käse, bitte.": "Five hundred grams of cheese, please.",
  "Fünfundachtzig. Mit „y“ in der Mitte?": "Eighty-five. With 'y' in the middle?",
  "Fünfzehn Euro im Mehrbettzimmer.": "Fifteen euros in a shared room.",
  "Fünfzehn? Puh.": "Fifteen? Wow.",
  "fünfzig": "fifty",
  "Für „am Montag\" reicht der Artikel: *el lunes*. Und *los lunes* heißt „montags, jeden Montag\". Wochentage schreibt man übrigens klein.": "For \"on Monday,\" just use the article: *el lunes*. And *los lunes* means \"on Mondays, every Monday.\" By the way, days of the week are not capitalized.",
  "Für „am Montag“ sagt man *el lunes*, für „montags“ *los lunes*. Ein *en lunes* gibt es nicht. Die Tage werden kleingeschrieben, und *sábado* und *domingo* bilden den Plural mit *-s*, die übrigen bleiben gleich: *los lunes*.": "For 'on Monday', you say *el lunes*, for 'on Mondays', *los lunes*. There's no *en lunes*. Days are lowercase, and *sábado* and *domingo* form the plural with *-s*, the others stay the same: *los lunes*.",
  "Für „schneide!“ nimmst du die *él*-Form: *él corta* wird zu *¡Corta!* Bei *-er* und *-ir* genauso: *él come* wird *¡Come!*, *él añade* wird *¡Añade!* Ein einziger Buchstabe entscheidet also zwischen Aussage und Anweisung.": "For \"cut!\" you use the *él* form: *él corta* becomes *¡Corta!* It's the same for *-er* and *-ir* verbs: *él come* becomes *¡Come!*, *él añade* becomes *¡Añade!* Just one letter changes a statement to a command.",
  "für (Gegenwert)": "for",
  "für (Zweck)": "for (purpose)",
  "für alle Fälle": "just in case",
  "Für alle Personen": "For all persons",
  "für die Zukunft": "looking to the future",
  "Für die Zukunft, sag mir vorher Bescheid.": "In the future, let me know beforehand.",
  "Für ein Gespräch stehe ich zur Verfügung.": "I am available for an interview.",
  "Für Gewohnheiten (*Iba al colegio en bici*), für Beschreibungen (*Era alto y llevaba gafas*), für Alter und Uhrzeit (*Tenía ocho años*, *Eran las tres*) und für Zustände (*Estaba cansado*). Es malt die Kulisse, nicht die Handlung.": "For habits (*Iba al colegio en bici*), for descriptions (*Era alto y llevaba gafas*), for age and time (*Tenía ocho años*, *Eran las tres*), and for states (*Estaba cansado*). It paints the background, not the action.",
  "für mich": "for me",
  "Für mich das Gleiche.": "For me, the same.",
  "Für mich einen Milchkaffee.": "For me, a coffee with milk.",
  "Für Monate und Jahreszeiten steht *en*: *en enero*, *en verano*. Für Wochentage steht der Artikel: *el lunes*. Und das Datum braucht *de*: *el quince de mayo*. Drei Muster, die man auseinanderhalten muss.": "For months and seasons, use *en*: *en enero*, *en verano*. For weekdays, use the article: *el lunes*. And dates need *de*: *el quince de mayo*. Three patterns to keep straight.",
  "Für Musik. An einer kleinen Schule.": "Music. At a small school.",
  "Für Pläne sagt man *voy a hablar*. Das Futur benutzt man vor allem für Vermutungen über die GEGENWART: *Serán las tres* (es wird wohl drei sein), *Estará durmiendo* (er schläft vermutlich). Das überrascht die meisten Lernenden.": "For plans, you say *voy a hablar*. The future tense is mainly used for speculations about the PRESENT: *Serán las tres* (it's probably three), *Estará durmiendo* (he's probably sleeping). This surprises most learners.",
  "Für spanische Ohren gibt es keinen Unterschied zwischen *b* und *v*: *vino* und *bino* klängen identisch. Deshalb fragen Spanier beim Buchstabieren oft „¿be o uve?“ – ist es ein B oder ein V?": "To Spanish ears, there's no difference between *b* and *v*: *vino* and *bino* sound identical. That's why Spaniards often ask when spelling, \"¿be o uve?\" – is it a B or a V?",
  "Für viele Spanier ist dieser Teil der wichtigste. Das Essen ist der Vorwand. Worauf es wirklich ankommt, ist das Gespräch.": "For many Spaniards, this part is the most important. The meal is just an excuse. What truly matters is the conversation.",
