  "Genau da klingelte es.": "Just then, the doorbell rang.",
  "Genau der. Das ist der Ort, wo wir uns kennengelernt haben.": "Exactly. That's the place where we met.",
  "Genau die. Sie sah mein Gesicht und lud mich nach oben ein.": "That's the one. She saw my face and invited me upstairs.",
  "Genau drei Ausnahmen": "Exactly three exceptions",
  "Genau hundert heißt *cien*: *cien euros*, *cien años*. Kommt etwas dazu, wird daraus *ciento*: *ciento uno*, *ciento cincuenta*. Und zwischen Hunderter und Rest steht KEIN *y*: *ciento veinte*, nicht *ciento y veinte*.": "Exactly one hundred is *cien*: *cien euros*, *cien años*. Add something, and it becomes *ciento*: *ciento uno*, *ciento cincuenta*. And there's NO *y* between hundreds and the rest: *ciento veinte*, not *ciento y veinte*.",
  "genau in dem Moment": "just then",
  "Genau, abends. Gleis fünf.": "Exactly, in the evening. Track five.",
  "Genau, es ist dieselbe. Sie heißt Subjuntivo.": "Exactly, it's the same. It's called the Subjunctive.",
  "Genau: ein Freund seit Jahren, kein alter Freund.": "Exactly: a friend for years, not an elderly friend.",
  "Genau.": "Exactly.",
  "Genau. Aber am Freitag hauen wir rein.": "Exactly. But on Friday, we'll go all out.",
  "Genau. Das Wort wächst, die Betonung wandert.": "Exactly. The word grows, the stress shifts.",
  "Genau. Die Endung ändert sich, das Wort nicht.": "Exactly. The ending changes, the word doesn't.",
  "Genau. Hat nichts mit „dasselbe\" zu tun.": "Exactly. Nothing to do with \"the same.\"",
  "Genau. Heute ist noch offen, gestern ist zu.": "Exactly. Today is still open, yesterday is closed.",
  "Genau. Heute wäre es „he hablado“.": "Exactly. Today it would be \"he hablado.\"",
  "Genau. Ich vermisse diese Sommer.": "Exactly. I miss those summers.",
  "Genau. Schau: deine Schwester und du. Siehst du den Unterschied?": "Exactly. Look: your sister and you. See the difference?",
  "Genau. So musst du nie wieder nachdenken.": "Exactly. That way, you never have to think twice.",
  "Genau. Und am Tresen ist es billiger.": "Exactly. And it's cheaper at the bar.",
  "Genau. Und für die Haare nehmen wir tener: sie hat lange Haare.": "Exactly. And for hair, we use tener: she has long hair.",
  "Genau. Und kannst du es mir auch erklären?": "Exactly. Can you explain it to me too?",
