  "Getrennt und mit Akzent fragt man: *¿Por qué no vienes?* Zusammen und ohne Akzent antwortet man: *Porque estoy cansado.* Ein Leerzeichen und ein Strich trennen Frage von Antwort.": "Separated and with an accent, you ask: *¿Por qué no vienes?* Together and without an accent, you answer: *Porque estoy cansado.* A space and a mark separate question from answer.",
  "Getrennt zahlen ist in Spanien unüblich – meist zahlt einer und man rechnet später untereinander ab.": "Splitting the bill is uncommon in Spain – usually one pays and you settle up later.",
  "Getrennte Rechnungen sind unüblich. Man sagt *pagamos a medias* (halbe-halbe) oder *hoy invito yo* (heute lade ich ein). Beim Einladen zahlt wirklich einer alles – das wechselt sich beim nächsten Mal.": "Separate bills are uncommon. You say *pagamos a medias* (split the bill) or *hoy invito yo* (it's my treat today). When treating, one person really pays for everything – and it switches next time.",
