  "Höflichkeit: *¿Podrías ayudarme?* Rat: *Yo que tú lo haría.* Vermutung über die Vergangenheit: *Serían las ocho.* Dieselbe Form, drei ganz verschiedene Einsätze – der Zusammenhang klärt es.": "Politeness: *¿Podrías ayudarme?* Advice: *Yo que tú lo haría.* Speculation about the past: *Serían las ocho.* The same form, three very different uses – context clarifies it.",
