  "Hostel, Ferienwohnung, Herberge": "Hostel, Vacation Rental, Lodge",
  "Hotels, Restaurants und Läden müssen in Spanien ein *libro de reclamaciones* vorhalten und auf Verlangen herausgeben. Der Eintrag geht an die Verbraucherbehörde. Allein die Bitte löst meist das Problem.": "Hotels, restaurants, and shops in Spain must have a *libro de reclamaciones* (complaint book) and provide it upon request. The entry goes to the consumer authority. Just asking for it often solves the problem.",
