  "Ich habe diese Vokabeln ausgewählt, weil Familie und Freunde zentrale Bestandteile unseres Lebens sind. Ein fundierter Wortschatz in diesem Bereich hilft dir, Beziehungen im Spanischen auszudrücken und zu vertiefen.": "I chose these words because family and friends are central to our lives. A strong vocabulary here helps you express and deepen relationships in Spanish.",
  "Ich habe diese Vokabeln ausgewählt, weil Musik, Ausgehen und Kultur zentrale Aspekte des Lebens sind, die oft im Alltag diskutiert werden. Diese Wörter helfen dir, dich in sozialen Situationen besser auszudrücken und neue Freundschaften zu schließen.": "I chose these words because music, going out, and culture are central aspects of life that are often discussed in daily life. These words help you express yourself better in social situations and make new friends.",
  "Ich habe diese Vokabeln ausgewählt, weil sie dir helfen werden, dich in deinem zukünftigen Berufsleben in spanischsprachigen Ländern zurechtzufinden. Diese Wörter decken die wichtigsten Aspekte der Arbeit und des Berufs ab und sind oft in Alltagssituationen zu hören.": "I've chosen these words because they'll help you navigate your future professional life in Spanish-speaking countries. These words cover key aspects of work and profession and are often heard in everyday situations.",
  "Ich habe diese Vokabeln ausgewählt, weil sie in vielen Alltagssituationen beim Reisen in Spanien sehr nützlich sind. Als angehender Reisender wirst du diese Wörter oft benötigen, um dich zurechtzufinden und mit Einheimischen zu kommunizieren.": "I chose these words because they're very useful in many everyday situations when traveling in Spain. As a future traveler, you'll often need these words to find your way and communicate with locals.",
