  "Ich will, aber ich kann nicht. Ich muss nämlich arbeiten.": "I want to, but I can't. I have to work, you see.",
  "Ich will, dass du mit ihm sprichst.": "I want you to talk to him.",
  "Ich will, dass du mit mir ins Kino kommst.": "I want you to come with me to the movies.",
  "Ich wohne an der Hauptallee.": "I live on the main avenue.",
  "Ich wohne in Berlin.": "I live in Berlin.",
