  "Jede Familie hat ihr Ritual.": "Every family has its ritual.",
  "Jede hat eigenes Parlament, eigene Bildungs- und Gesundheitspolitik. Deshalb unterscheiden sich Schulferien, Feiertage und sogar Ladenöffnungszeiten von Region zu Region – ein einheitliches Spanien gibt es im Alltag nicht.": "Each has its own parliament, education, and health policies. That's why school holidays, public holidays, and even store hours vary from region to region – there's no uniform Spain in daily life.",
  "Jede Lektion bringt neue Wörter, einen Dialog und Übungen – und holt drei alte Wörter zurück, damit nichts verloren geht. Ab 80 % richtigen Antworten sitzt eine Lektion. Darunter empfiehlt die App eine zweite Runde, blockiert dich aber nicht.": "Each lesson brings new words, a dialogue, and exercises – and revisits three old words, so nothing gets lost. With 80% correct answers, you complete a lesson. Below that, the app suggests another round but doesn't block you.",
