  "Kastilisch spricht man überall. Dazu Katalanisch in Katalonien, Valencia und auf den Balearen, Galicisch in Galicien, Baskisch im Baskenland. Schilder sind dort zweisprachig – niemand erwartet, dass du die zweite Sprache kannst.": "Castilian Spanish is spoken everywhere. Additionally, Catalan is spoken in Catalonia, Valencia, and the Balearic Islands, Galician in Galicia, and Basque in the Basque Country. Signs are bilingual there – no one expects you to know the second language.",
