  "Kritik annehmen": "Accepting criticism",
  "Kritik läuft in Spanien fast immer unter vier Augen – vor der Gruppe gilt sie als Bloßstellung.": "In Spain, criticism is almost always given one-on-one – in a group, it's seen as embarrassing.",
  "Kritik weich verpacken": "Softening criticism",
  "Kulisse im Imperfekt: *Era de noche y llovía.* Handlung im Indefinido: *Salí de casa.* Wende: *De repente…* Auflösung: *Al final…* Wer diese vier Schichten trennt, erzählt automatisch in den richtigen Zeiten.": "Backdrop in the Imperfect: *Era de noche y llovía.* Action in the Preterite: *Salí de casa.* Turning point: *De repente…* Resolution: *Al final…* Separating these four layers helps you automatically use the right tenses.",
  "Kulisse oder Handlung": "Backdrop or Action",
  "Kulisse und Ereignis unterscheiden": "Distinguish background from events",
  "Kulisse und Handlung verweben": "Weaving background and action",
  "Kultur, Meinung und der Subjuntivo": "Culture, Opinion, and the Subjunctive",
  "Künftig sage ich dir vorher Bescheid. Danke, dass du es sagst.": "In the future, I'll let you know beforehand. Thanks for mentioning it.",
  "Kürbisse galten im Mittelalter als Mittel gegen Begehren – wer einen bekam, wusste Bescheid. Heute heißt *dar calabazas* schlicht „einen Korb geben\". Die Herkunft kennt kaum noch jemand, die Wendung alle.": "In the Middle Ages, pumpkins were seen as a remedy against desire – if you received one, you got the message. Today, *dar calabazas* simply means \"to reject someone.\" Few know the origin, but everyone knows the phrase.",
