  "laufen": "to run",
  "Läuft etwas und wird unterbrochen, steht das Laufende im Imperfekt und die Unterbrechung im Indefinido: *Mientras cocinaba, sonó el teléfono.* *Cuando dormía, llamaron a la puerta.* Das Muster ist immer gleich.": "When something is ongoing and gets interrupted, the ongoing action is in the Imperfect and the interruption is in the Preterite: *Mientras cocinaba, sonó el teléfono.* *Cuando dormía, llamaron a la puerta.* The pattern is always the same.",
  "Laut heißt nicht böse": "Loud doesn't mean angry",
  "Lautstärke ist in Spanien kein Streitsignal: Zwei Menschen können sehr laut und sehr freundschaftlich diskutieren.": "Volume isn't a sign of conflict in Spain: People can discuss loudly and still be friendly.",
