  "Lena, was machen wir morgen?": "Lena, what are we doing tomorrow?",
  "Lerne nie *mesa*, sondern immer *la mesa*. Das Geschlecht lässt sich nicht ableiten – *la mesa* ist weiblich, obwohl „der Tisch“ im Deutschen männlich ist. Wer den Artikel mitlernt, muss ihn nie wieder raten.": "Never learn *mesa* alone, always learn *la mesa*. You can't guess the gender – *la mesa* is feminine, even though \"table\" in English is neutral. Learn the article with the noun, and you'll never have to guess.",
