  "Machu Picchu": "Machu Picchu",
  "Machu Picchu liegt in den Anden in Peru, hoch oben zwischen den Bergen. Es ist eine Stadt aus Stein, erbaut von den Inka.": "Machu Picchu is located in the Andes in Peru, high up between the mountains. It's a city of stone, built by the Incas.",
