  "Madrids Metro fährt bis 1:30 Uhr, danach übernehmen die „búhos“ – Nachtbusse, die nach Eulen benannt sind.": "Madrid's metro runs until 1:30 AM, then the \"búhos\" – night buses named after owls – take over.",
