  "mala leche ist stärker als es klingt": "mala leche is stronger than it sounds",
  "Man bleibt nicht sitzen: eine Tapa, ein Getränk, weiter zur nächsten Bar. Drei bis fünf Stationen sind normal. Wer den ganzen Abend in einem Lokal verbringt, hat nicht getapeado, sondern zu Abend gegessen.": "You don't stay put: one tapa, one drink, then on to the next bar. Three to five stops are normal. Spending the whole evening in one place isn't tapear, it's having dinner.",
  "Man darf hier nicht durchfahren.": "You can't go down this street.",
  "man darf nicht": "you cannot",
  "Man hängt *-ía* an den Infinitiv: *querer → querría*, *gustar → gustaría*, *poder → podría*, *ser → sería*. *Quiero una habitación* ist eine Forderung, *Querría una habitación* eine Bitte. Ein Buchstabe, ein anderer Ton.": "Add *-ía* to the infinitive: *querer → querría*, *gustar → gustaría*, *poder → podría*, *ser → sería*. *Quiero una habitación* is a demand, *Querría una habitación* is a request. One letter changes the tone.",
  "Man hängt an den Infinitiv: *salir → saldrá*, *llegar → llegará*, *ser → será*. Im Alltag nimmt man *ir a* (*va a salir*), aber Durchsagen und Fahrpläne benutzen diese Form. Du musst sie erkennen, nicht bilden.": "Add to the infinitive: *salir → saldrá*, *llegar → llegará*, *ser → será*. In daily life, people use *ir a* (*va a salir*), but announcements and schedules use this form. You need to recognize it, not form it.",
  "Man hat Jahre, man ist sie nicht": "You have years, you don't 'be' them",
  "Man hat mir die Brieftasche gestohlen.": "My wallet has been stolen.",
  "Man hört die Musik ziemlich. Könntest du sie leiser machen?": "The music is quite loud. Could you turn it down?",
  "Man isst sie mittags und fast nie abends. Und man macht sie für viele: Eine Paella für zwei Personen zu kochen ergibt keinen Sinn.": "It's eaten at lunchtime, almost never in the evening. And it's made for many: Cooking paella for two people doesn't make sense.",
  "Man kann jeden Satz durch die Stimme zur Frage machen: *¿Vienes mañana?* Die Stimme geht am Ende hoch. Für ein „oder?“ hängt man *¿verdad?* oder *¿no?* an: *Hablas español, ¿verdad?*": "You can turn any statement into a question with your voice: *¿Vienes mañana?* Your voice rises at the end. For a “right?” you add *¿verdad?* or *¿no?*: *Hablas español, ¿verdad?*",
  "Man kauft nicht schweigend ein. Die Verkäuferin fragt dich, wofür du es willst, und sagt dir, was heute am besten ist. Manchmal gibt sie dir vorher etwas zum Probieren.": "You don't shop in silence. The vendor asks what you need it for and tells you what's best today. Sometimes, they let you try it first.",
