  "Märchen zeigen den Unterschied am reinsten: *Érase una vez un rey que tenía tres hijas* (Kulisse, Imperfekt). *Un día, el rey llamó a la mayor* (Handlung, Indefinido). Wer Märchen liest, übt beide Zeiten nebenbei.": "Fairy tales show the difference clearly: *Érase una vez un rey que tenía tres hijas* (setting, Imperfect). *Un día, el rey llamó a la mayor* (action, Preterite). Reading fairy tales helps you practice both tenses.",
