  "Melden im Perfekt": "Report in the present perfect",
  "Melden und Anliegen: *Buenos días, soy Tom de… Llamo por…* Klären. Zusammenfassen: *Entonces quedamos en que…* Abschließen: *Se lo confirmo por correo.* Der dritte Schritt ist der wichtigste – er verhindert Missverständnisse.": "Introduce and state your purpose: *Buenos días, soy Tom de… Llamo por…* Clarify. Summarize: *Entonces quedamos en que…* Conclude: *Se lo confirmo por correo.* The third step is crucial – it prevents misunderstandings.",
  "Mengen angeben (ein Kilo, 200 Gramm…)": "Specify quantities (one kilo, 200 grams…)",
  "Mengen bestellen wie ein Local": "Order quantities like a local",
  "Mengen brauchen „de\"": "Quantities need \"de\"",
  "Mengen für die Gruppe angeben": "Specify quantities for the group.",
  "Mengen und Wechselkurse": "Amounts and exchange rates",
  "Mengen, Preise und „Haben Sie…?\"": "Amounts, Prices & \"Do You Have...?\"",
  "Mengenangaben brauchen *de*: *un kilo DE tomates*, *un litro DE leche*. Das kleine Wort wegzulassen ist DER Anfängerfehler – jetzt nicht mehr deiner.": "Quantities need *de*: *un kilo DE tomates*, *un litro DE leche*. Leaving out this small word is THE beginner's mistake – not yours anymore.",
  "Mengenangaben mit de": "Quantities with de",
  "Menschen beschreiben (*es simpático, lleva gafas*), Gefühle sagen (*estoy nervioso, tengo ganas*), von heute berichten (*he hablado, he visto*), Wiederholungen vermeiden (*se lo doy*) und ein Gespräch führen (*¿ah sí?, qué bien*).": "Describing people (*es simpático, lleva gafas*), expressing feelings (*estoy nervioso, tengo ganas*), talking about today (*he hablado, he visto*), avoiding repetition (*se lo doy*), and having a conversation (*¿ah sí?, qué bien*).",
  "Menschen beschreiben, ohne unhöflich zu werden": "Describe People Politely",
  "Menschen charakterlich beschreiben": "Describing people's character",
  "merken": "realize",
