  "Mexiko": "Mexico",
  "Mexiko hat mehr Spanischsprecher als Spanien und Argentinien zusammen. „Reines Spanisch\" ist ein Mythos – jede Region hält ihre Variante für die klarste. Wichtig ist nur Verständlichkeit, nicht Herkunft.": "Mexico has more Spanish speakers than Spain and Argentina combined. \"Pure Spanish\" is a myth – each region considers its version the clearest. What's important is being understood, not where you're from.",
