  "Mit „érase una vez\". Wie unser „es war einmal\".": "With \"érase una vez.\" Like our \"once upon a time.\"",
  "Mit *estar* beschreibst du eine Stimmung: *estoy triste*, *está nervioso*. Mit *tener* etwas, das man „hat“: *tengo miedo*, *tengo ganas*, *tengo sueño*. Faustregel: Steht ein Adjektiv, nimm *estar*; steht ein Substantiv, nimm *tener*.": "With *estar*, you describe a mood: *estoy triste*, *está nervioso*. With *tener*, it's something you \"have\": *tengo miedo*, *tengo ganas*, *tengo sueño*. Rule of thumb: If it's an adjective, use *estar*; if it's a noun, use *tener*.",
  "Mit *primero*, *luego*, *después* und *por fin* reihst du auf: *Primero me levanto, luego desayuno, después salgo de casa y por fin llego al trabajo.* Damit erzählst du einen ganzen Tag.": "With *primero*, *luego*, *después*, and *por fin*, you sequence events: *Primero me levanto, luego desayuno, después salgo de casa y por fin llego al trabajo.* This way, you narrate an entire day.",
  "Mit *ser* wird ein Adjektiv zum Charakter, mit *estar* zur Stimmung: *Es aburrido* heißt „er ist langweilig“, *Está aburrido* heißt „er langweilt sich“. Genauso: *es guapa* (sie ist hübsch) und *está guapa* (sie sieht heute hübsch aus).": "With *ser*, an adjective describes character, with *estar*, it describes mood: *Es aburrido* means \"he is boring,\" *Está aburrido* means \"he is bored.\" Similarly: *es guapa* (she is pretty) and *está guapa* (she looks pretty today).",
  "Mit *tener* nennst du das, was du hast: *tengo fiebre*, *tengo tos*, *tengo dolor de cabeza*. Mit *estar* den Zustand: *estoy resfriado*, *estoy enfermo*, *estoy cansado*. Beides kommt vor, nur nie gemischt.": "With *tener*, you name what you have: *tengo fiebre*, *tengo tos*, *tengo dolor de cabeza*. With *estar*, you describe the state: *estoy resfriado*, *estoy enfermo*, *estoy cansado*. Both are used, just never mixed.",
  "Mit Älteren immer. Es ist eine Frage des Respekts.": "With older people, always. It's a matter of respect.",
  "Mit Ausweis die Hälfte. Das wären neun insgesamt.": "With ID, it's half price. That'll be nine total.",
  "Mit Bargeld, weil Ana keine Karte hat": "With cash, because Ana doesn't have a card",
