  "Mit der Europäischen Krankenversicherungskarte wird man in Spanien im öffentlichen System behandelt wie ein Einheimischer.": "With the European Health Insurance Card, you get treated like a local in Spain's public system.",
  "Mit der Europäischen Krankenversicherungskarte wirst du im öffentlichen *centro de salud* behandelt wie ein Spanier. Ohne Karte zahlst du erst und reichst später ein. Privatpraxen rechnen immer direkt ab.": "With the European Health Insurance Card, you're treated like a local at public *centro de salud*. Without it, you pay upfront and claim later. Private clinics always bill directly.",
  "Mit der Metro, drei Stationen. Oder eine halbe Stunde zu Fuß.": "By metro, three stops. Or a half-hour walk.",
