  "müssen": "to have to",
  "Na ja, das passiert jedem.": "Well, that happens to everyone.",
  "Na los, erzähl.": "Go on, tell me.",
  "Nach „es normal que\" kommt es von selbst.": "After \"es normal que,\" it just follows naturally.",
  "Nach „si“ steht nie der Subjuntivo der Gegenwart – das ist eine der wenigen absoluten Regeln des Spanischen.": "After \"si\" (if), never use the present subjunctive – it's one of the few absolute rules in Spanish.",
  "Nach *antes de que* steht IMMER der Subjuntivo, egal ob Zukunft, Gewohnheit oder Vergangenheit: *Llámame antes de que salgas.* *Siempre me llamaba antes de que saliera.* Logisch: Was davor liegt, ist noch nicht geschehen.": "After *antes de que*, ALWAYS use the Subjunctive, whether future, habit, or past: *Llámame antes de que salgas.* *Siempre me llamaba antes de que saliera.* Makes sense: What comes before hasn't happened yet.",
  "Nach *ojalá* steht nicht *viene*, sondern *venga*. Nicht *es*, sondern *sea*. Diese Formen kennst du längst – aus dem Sie-Befehl: *venga*, *sea*, *tenga*. Es ist dieselbe Form, nur in anderer Aufgabe: der Subjuntivo.": "After *ojalá*, you don't use *viene*, but *venga*. Not *es*, but *sea*. You already know these forms – from the formal command: *venga*, *sea*, *tenga*. It's the same form, just used differently: the Subjunctive.",
  "Nach *poder*, *querer*, *tener que* und *saber* steht das zweite Verb ungebeugt: *Quiero comer*, *Puedo ayudar*, *Tengo que salir*. Nur das erste Verb wird gebeugt – das zweite bleibt, wie es im Wörterbuch steht.": "After *poder*, *querer*, *tener que*, and *saber*, the second verb stays in its base form: *Quiero comer*, *Puedo ayudar*, *Tengo que salir*. Only the first verb changes – the second stays as it is in the dictionary.",
  "Nach *ser* richtet sich das Adjektiv nach der Person: *Tom es alto*, *Ana es alta*, *ellos son altos*. Auf *-o* endende Adjektive wechseln zu *-a*; auf *-e* oder Konsonant endende bleiben gleich: *joven*, *jóvenes*.": "After *ser*, adjectives match the person: *Tom es alto*, *Ana es alta*, *ellos son altos*. Adjectives ending in *-o* change to *-a*; those ending in *-e* or a consonant stay the same: *joven*, *jóvenes*.",
  "Nach *ser* steht der Beruf nackt: *Soy profesor*, *Ella es médica*. Ein *un/una* kommt erst dazu, wenn ein Adjektiv folgt: *Es una médica excelente*.": "After *ser*, professions stand alone: *Soy profesor*, *Ella es médica*. You only add *un/una* if there's an adjective: *Es una médica excelente*.",
  "Nach *si* der Subjuntivo des Imperfekts, in der Folge der Konditional: *Si tuviera tiempo, viajaría.* Nie umgekehrt. Der Bau ist derselbe wie im Deutschen: „Wenn ich Zeit hätte, würde ich reisen.\"": "After *si*, use the past subjunctive, followed by the conditional: *Si tuviera tiempo, viajaría.* Never the other way around. This structure is similar to English: \"If I had time, I would travel.\"",
  "Nach Ausstattung fragen": "Ask about amenities",
  "nach dem Abschluss": "upon finishing",
  "Nach dem Alter fragen und antworten": "Ask and answer about age",
  "Nach dem Nachdruck kommt das Angebot: *¿Buscamos una solución?* So kann dein Gegenüber nachgeben, ohne zu verlieren. Und wenn er einlenkt: *De acuerdo entonces, se lo agradezco.*": "After making your point, offer a solution: *¿Buscamos una solución?* This way, the other person can concede without losing face. And if they agree: *De acuerdo entonces, se lo agradezco.*",
  "Nach dem Studium zog sie um.": "After finishing her degree, she moved.",
  "nach dem Superlativ": "after the superlative",
  "Nach dem Weg fragen": "Asking for directions",
  "Nach dem Weg fragen und Antworten verstehen, Fahrkarten und Zimmer buchen, reklamieren, zum Arzt gehen, einen Notruf absetzen und von der Reise erzählen. Das ist alles, was eine Reise braucht.": "Ask for directions and understand answers, book tickets and rooms, make complaints, visit a doctor, make an emergency call, and talk about your trip. That's everything a trip needs.",
  "Nach dem Weg fragen und die Antwort auch verstehen – *siga recto*, *gire a la derecha*, *cruce la plaza*. Dazu Fahrpläne, Tickets, Verbote und das unpersönliche *se* auf jedem Schild: *se prohíbe*, *se ruega*, *no se puede*.": "Asking for directions and understanding the answer – *siga recto* (go straight), *gire a la derecha* (turn right), *cruce la plaza* (cross the square). Plus schedules, tickets, prohibitions, and the impersonal *se* on every sign: *se prohíbe* (it's prohibited), *se ruega* (please), *no se puede* (you can't).",
  "Nach den Träumen anderer fragen": "Asking about others' dreams",
  "Nach der Dauer fragen": "Asking about duration",
  "Nach der ganzen Arbeit?": "After all that work?",
  "Nach der Herkunft fragen": "Asking about someone's origin",
  "Nach der Rechnung fragen": "Asking for the bill",
  "Nach der Reise war ich völlig erledigt.": "After the trip, I was exhausted.",
