  "Nach der Uhrzeit fragen und sie sagen": "Ask for and tell the time",
  "Nach dijo que rutscht der Satz eine Zeitstufe zurück.": "After 'said', the sentence shifts back a tense.",
  "Nach einem Diebstahl brauchst du die *denuncia* von der *comisaría* – ohne sie zahlt keine Versicherung. Bei verlorenem Pass hilft das Konsulat, aber auch dort verlangt man zuerst die Anzeige.": "After a theft, you need the *denuncia* from the *comisaría* – without it, no insurance will pay. If you lose your passport, the consulate can help, but they also require the report first.",
