  "Nach und nach werden wir besser.": "Little by little, we're getting better.",
  "Nach Wörtern und Bedeutungen fragen": "Asking about words and meanings",
  "Nach Wunsch (*ojalá*, *espero que*), nach Gefühl und Wertung (*me alegro de que*, *es raro que*), nach Zweifel (*dudo que*, *puede que*) und nach verneinter Meinung (*no creo que*). Vier Auslöser – wer sie kennt, trifft die Form meistens.": "With wishes (*ojalá*, *espero que*), feelings and judgments (*me alegro de que*, *es raro que*), doubt (*dudo que*, *puede que*), and negative opinions (*no creo que*). Four triggers—know them, and you'll usually get the form right.",
