  "Nachts stellen die Kinder ihre Schuhe ans Fenster, dazu Wasser für die Kamele. Am nächsten Morgen stehen die Schuhe nicht mehr allein da.": "At night, children place their shoes by the window, along with water for the camels. The next morning, the shoes are no longer alone.",
