  "Nationalitäten richten sich nach der Person: ein Mann ist *alemán*, eine Frau *alemana*. Und anders als im Deutschen schreibt man sie klein.": "Nationalities match the person: a man is *alemán*, a woman *alemana*. And unlike in English, they are written in lowercase.",
