  "neben": "next to",
  "Neben den nationalen gibt es regionale und städtische. Wer in Madrid arbeitet und in Toledo wohnt, hat zwei verschiedene Kalender. Deshalb die Alltagsfrage: *¿Aquí es festivo mañana?*": "Besides national holidays, there are regional and city-specific ones. If you work in Madrid and live in Toledo, you have two different calendars. Hence the everyday question: *¿Aquí es festivo mañana?*",
  "neben der Bar": "next to the bar",
