  "Nein danke, ich habe eine dabei. Bis bald!": "No thanks, I have one with me. See you soon!",
  "Nein sagen": "Saying no",
  "Nein, aber am Anfang hat es mich befremdet. Drüben benutzt man viel das Sie.": "No, but at first it surprised me. Over there, we use formal titles a lot.",
  "Nein, danke. Die Rechnung, bitte.": "No, thank you. The bill, please.",
  "Nein, das ist kein Tapear. Wir ziehen weiter.": "No, that's not tapear. We move on.",
  "Nein, die Linien sind gelb. Das ist verboten.": "No, the lines are yellow. That's not allowed.",
  "Nein, heute lade ich dich ein. Du hast das Kino bezahlt.": "No, today it's my treat. You paid for the cinema.",
  "Nein, ich bin aus Madrid. Aber wir sind seit Jahren befreundet.": "No, I'm from Madrid. But we've been friends for years.",
  "Nein, ich fuhr mit dem Rad. Ich brauchte zehn Minuten.": "No, I rode my bike. It took ten minutes.",
