  "Nein, keine Sorge. Gefällt es dir?": "No, don't worry. Do you like it?",
  "Nein, meine Eltern und meine Schwester sind in Deutschland.": "No, my parents and my sister are in Germany.",
  "Nein, mit einem. T–O–M.": "No, with one. T–O–M.",
