  "Nein, sehr billig. Die teuren sind am Platz.": "No, very cheap. The expensive ones are in the square.",
  "Nein, sie ist im Schlussverkauf. Sie ist genauso gut.": "No, it's on sale. It's just as good.",
  "Nein, sie ist ziemlich nah. Zehn Minuten zu Fuß.": "No, it's pretty close. Ten minutes on foot.",
  "Nein, sonntags arbeite ich nie.": "No, I never work on Sundays.",
  "Nein, zehn Minuten zu Fuß.": "No, ten minutes on foot.",
  "Nein, zwei Tage Homeoffice. Und du?": "No, two days working from home. How about you?",
