  "Nein. Ist das schwierig?": "No. Is that difficult?",
  "Nein. Nach der Schule zog sie nach Madrid.": "No. After school, she moved to Madrid.",
  "Nein. Was macht man da genau?": "No. What exactly do they do?",
  "Nennen Sie mir die genaue Adresse.": "Tell me the exact address.",
  "nervös": "nervous",
  "nett": "nice",
  "nett, sympathisch": "nice, friendly",
  "neu": "new",
  "neulich": "the other day",
  "Neulich sah ich Carmen.": "The other day, I saw Carmen.",
  "Neulich? Welcher Tag?": "Recently? Which day?",
  "Neun decken den Alltag ab": "Nine cover everyday life",
  "Neun von zehn Spanischsprechenden leben nicht in Spanien – wer Spanisch lernt, lernt vor allem eine amerikanische Sprache.": "Nine out of ten Spanish speakers don't live in Spain – learning Spanish is mostly about learning an American language.",
  "neunzig": "ninety",
  "Nicht alle Pilger sind religiös. Manche gehen, um nachzudenken, andere, weil sie ein paar Tage allein sein wollen. Man schläft in einfachen Herbergen und läuft viele Stunden.": "Not all pilgrims are religious. Some walk to reflect, others to spend a few days alone. You sleep in simple hostels and walk for hours.",
  "Nicht am Wortschatz – den bekommt man geschenkt. Sondern daran, ob jemand *era* und *fue* auseinanderhält. Wer das kann, wird in Spanien nicht mehr langsamer angesprochen. Das ist die eigentliche Schwelle.": "Not by vocabulary – that's given to you. But by whether someone can distinguish *era* from *fue*. If you can do that, people in Spain won't slow down their speech for you. That's the real threshold.",
  "nicht aufgeben": "don't give up",
  "Nicht besonders. Mir tut der Kopf weh.": "Not really. My head hurts.",
  "Nicht besonders. Musik mag ich lieber.": "Not really. I prefer music.",
  "nicht dass noch": "lest",
  "Nicht du magst etwas – etwas gefällt dir. *Me gusta el café*, *me gustan los libros*. Das Verb richtet sich nach der Sache, nicht nach dir. Dieselbe Bauweise steckt später in *me parece*, *me apetece* und *se me olvidó*.": "It's not you liking something – something pleases you. *Me gusta el café*, *me gustan los libros*. The verb matches the thing, not you. The same structure is in *me parece*, *me apetece*, and *se me olvidó* later on.",
  "Nicht du tust weh, sondern der Körperteil tut DIR weh: *Me duele la cabeza* (Einzahl), *Me duelen los pies* (Mehrzahl). Das Verb richtet sich nach dem, was schmerzt – nicht nach der Person.": "It's not you who hurts, but the body part that hurts YOU: *Me duele la cabeza* (singular), *Me duelen los pies* (plural). The verb agrees with what hurts – not with the person.",
  "Nicht Freitag der 13., sondern *martes trece*. Der Spruch dazu: *En martes, ni te cases ni te embarques* – dienstags weder heiraten noch verreisen. In Griechenland und Italien gilt derselbe Wochentag.": "Not Friday the 13th, but *martes trece*. The saying goes: *En martes, ni te cases ni te embarques* – on Tuesdays, neither marry nor embark on a journey. The same day is considered unlucky in Greece and Italy.",
  "Nicht ich habe es vergessen – es hat sich mir vergessen: se me olvidó.": "Not I forgot it – it forgot itself to me: se me olvidó.",
  "Nicht ich mag etwas – etwas gefällt mir. Das Verb richtet sich nach der Sache.": "It's not 'I like something' – it's 'something pleases me'. The verb matches the thing.",
  "Nicht ins Fettnäpfchen treten": "Avoid faux pas",
  "Nicht jeder Flamenco ist traurig. Es gibt fröhliche Stile für Feste und andere, sehr ernste, die fast ohne Musik gesungen werden. Es kommt auf den Moment an.": "Not every flamenco is sad. There are joyful styles for celebrations and others, very serious, sung almost without music. It depends on the moment.",
  "nicht mehr": "no longer",
  "Nicht mehr Sätze aneinanderreihen, sondern eine Geschichte aufbauen: *érase una vez*, *de repente*, *al final*. Wer eine Anekdote auf Spanisch erzählen kann, wird nicht mehr als Anfänger behandelt.": "Not just stringing sentences together, but building a story: *érase una vez* (once upon a time), *de repente* (suddenly), *al final* (in the end). If you can tell an anecdote in Spanish, you're no longer seen as a beginner.",
  "Nicht mehr. Das Dorf hat sich sehr verändert.": "Not anymore. The village has changed a lot.",
  "nicht satt werden": "to remain hungry",
  "Nicht wie im Englischen": "Not like in English",
  "nicht, nein": "no",
  "nichts": "nothing",
  "Nichts Schlimmes. Ich vermisse meine Familie.": "Nothing bad. I miss my family.",
  "Nichts, es ist für alles gesorgt": "Nothing, everything is taken care of.",
  "Nichts. Also, drei Eier und eine halbe Zwiebel.": "Nothing. Well, three eggs and half an onion.",
  "Nichts. Es reimt sich nur. Ana hat es mir erklärt.": "Nothing. It just rhymes. Ana explained it to me.",
  "nie": "never",
  "Nie „hay el banco“": "Never “hay el banco”",
  "Niemals mit Wasser anstoßen": "Never toast with water",
  "niemand": "nobody",
  "Niemand erwartet von Lernenden, dass sie *vos* benutzen. Aber wer argentinische Musik hört oder Serien schaut, trifft es ständig. Es zu erkennen reicht völlig – und ein *tú* versteht dort auch jeder.": "No one expects learners to use *vos*. But if you listen to Argentine music or watch shows, you'll encounter it often. Recognizing it is enough – and everyone there understands *tú* too.",
  "Niemand korrigiert dich": "No one corrects you",
  "Niemand lässt alles auf einmal. Nach und nach.": "No one leaves everything at once. Bit by bit.",
  "Niemand unterbricht dich wegen eines falschen Artikels. Aber wer nur mit Ja und Nein antwortet, wird nicht wieder gefragt. Ein Fehler in einer Geschichte ist besser als ein perfekter Einzelsatz.": "No one interrupts you for a wrong article. But if you only answer with Yes or No, you won't be asked again. A mistake in a story is better than a perfect single sentence.",
  "Nimm den Schirm für alle Fälle.": "Take the umbrella just in case.",
  "Nimm den Stadtplan.": "Grab the city map.",
  "Nimm die *ellos*-Form des Indefinido, streiche *-ron*, hänge *-ra* an: *tuvieron → tuviera*, *pudieron → pudiera*, *fueron → fuera*, *supieron → supiera*. Alle Unregelmäßigkeiten wandern mit – man muss nichts Neues lernen.": "Take the *ellos* form of the simple past, remove *-ron*, add *-ra*: *tuvieron → tuviera*, *pudieron → pudiera*, *fueron → fuera*, *supieron → supiera*. All irregularities carry over – nothing new to learn.",
  "Nimm die *yo*-Form im Präsens, streiche das *-o* und tausche den Vokal: *hablo → hable*, *como → coma*, *vivo → viva*. Bei *-ar* kommt *e*, bei *-er* und *-ir* kommt *a*. Genau umgekehrt zur normalen Endung.": "Take the *yo* form in the present tense, drop the *-o* and swap the vowel: *hablo → hable*, *como → coma*, *vivo → viva*. For *-ar* verbs, use *e*, and for *-er* and *-ir* verbs, use *a*. It's the opposite of the usual ending.",
  "Nimm die Jacke, es ist kalt.": "Grab the jacket, it's cold.",
  "Nimm die Linie vier.": "Take line four.",
