  "Norden, Süden und alles dazwischen": "North, South, and In Between",
  "Norden: Fisch, Eintöpfe, Sauerrahm. Zentrum: Fleisch aus dem Ofen, Hülsenfrüchte. Süden: kalte Suppen, Frittiertes, viel Olivenöl. Levante: Reis. Wer nach „spanischer Küche\" fragt, bekommt vier verschiedene Antworten.": "North: fish, stews, sour cream. Center: oven-baked meats, legumes. South: cold soups, fried foods, lots of olive oil. Levante: rice. Ask about \"Spanish cuisine\" and you'll get four different answers.",
