  "Nur drei Verben sind im Imperfekt unregelmäßig – ser, ir und ver. Sonst ist es die verlässlichste Zeitform des Spanischen.": "Only three verbs are irregular in the imperfect – ser, ir, and ver. Otherwise, it's the most reliable tense in Spanish.",
