  "Oha! Und was machst du?": "Wow! And what are you going to do?",
  "ohne böses Blut": "no hard feelings",
  "ohne es zu merken": "without realizing",
  "Ohne es zu merken bin ich schon sechs Monate hier.": "Without realizing it, I've been here for six months.",
  "Ohne es zu merken vergingen zwei Stunden.": "Without realizing it, two hours passed.",
  "Ohne Klimaanlage ist es heiß.": "It's hot without air conditioning.",
  "Ohne Kurs weitermachen": "Continuing without the course",
  "Ohne Kurs zerfällt eine Sprache in etwa einem Jahr. Mit zwanzig Minuten am Tag bleibt sie: eine Serie ohne Untertitel, ein Podcast beim Kochen, ein Gespräch pro Woche. *El idioma se mantiene usándolo* – mehr Methode braucht es ab hier nicht.": "Without practice, a language fades in about a year. With twenty minutes a day, it stays: a series without subtitles, a podcast while cooking, a conversation a week. *El idioma se mantiene usándolo* – no more method is needed from here.",
  "Ohne Objektpronomen klingt Spanisch stockend: Statt „Compro el pan y como el pan“ sagt man „Compro el pan y lo como“.": "Without object pronouns, Spanish sounds choppy: Instead of \"I buy the bread and eat the bread,\" you say \"I buy the bread and eat it.\"",
  "ohne Untertitel": "without subtitles",
  "Ohne Untertitel verliere ich den Faden.": "Without subtitles, I lose track.",
