  "Patagonien liegt im Süden Chiles und Argentiniens. Es ist eine riesige und fast leere Region: Es gibt Berge, Seen, Gletscher und sehr viel Wind.": "Patagonia is in the south of Chile and Argentina. It's a vast and almost empty region: There are mountains, lakes, glaciers, and a lot of wind.",
