  "porque, pero, cuando": "because, but, when",
  "Postkarte? Schick ihr eine Sprachnachricht, das geht schneller.": "Postcard? Send her a voice message, it's faster.",
  "Postkarten sind in Spanien fast verschwunden – geschrieben wird per Sprachnachricht, oft minutenlang.": "Postcards have almost disappeared in Spain – people send voice messages, often minutes long.",
  "Präpositionen, Nebensätze, Vergleiche": "Prepositions, clauses, comparisons",
  "Präsens, beide Vergangenheiten und ihr Unterschied, Futur, Konditional, der Subjuntivo in Gegenwart und Vergangenheit, reale und irreale Bedingungen. Das ist das komplette Gerüst der Sprache. Was jetzt noch fehlt, ist kein System mehr – nur Wortschatz.": "Present, both past tenses and their difference, future, conditional, the subjunctive in present and past, real and unreal conditions. This is the complete framework of the language. What remains now is not a system anymore – just vocabulary.",
  "Präsens, beide Vergangenheiten und ihr Unterschied, Plusquamperfekt, Futur, Konditional, Subjuntivo in Gegenwart und Vergangenheit, reale und irreale Bedingungen. Mehr Grammatik hat diese Sprache nicht. Was jetzt noch fehlt, ist Wortschatz – und den sammelt man beim Leben, nicht beim Lernen.": "Present, both past tenses and their difference, pluperfect, future, conditional, subjunctive in present and past, real and unreal conditions. There's no more grammar in this language. What's missing now is vocabulary – and you gather that by living, not just learning.",
  "Präsens: *Si llueve, nos quedamos.* Futur: *Si llueve, nos quedaremos.* Befehl: *Si llueve, quédate en casa.* Alle drei sind richtig; im Alltag hört man am häufigsten das Präsens.": "Present: *Si llueve, nos quedamos.* Future: *Si llueve, nos quedaremos.* Command: *Si llueve, quédate en casa.* All three are correct; in everyday speech, the present is most common.",
  "Präsentieren": "Presenting",
  "Präsentieren und gliedern": "Presenting and structuring",
