  "Redewendungen, Feste, Aberglaube, Musik. Modul 6 hat weniger Grammatik gebracht als jedes andere – dafür das, was man in keinem Lehrbuch findet und ohne das man immer Ausländer bleibt.": "Idioms, festivals, superstitions, music. Module 6 brought less grammar than any other – but it brought what you won't find in textbooks and without which you'll always feel like a foreigner.",
  "Referenzen auf Anfrage.": "References available upon request.",
  "Reflexive Verben": "Reflexive verbs.",
  "Reflexive Verben richtig bilden": "Forming reflexive verbs correctly.",
  "Reflexive Verben tragen im Wörterbuch ein *-se*: *levantarse*. Beim Beugen wandert es nach vorn und passt sich an: *me levanto*, *te levantas*, *se levanta*, *nos levantamos*, *os levantáis*, *se levantan*.": "Reflexive verbs have a *-se* in the dictionary: *levantarse*. When conjugating, it moves to the front and adjusts: *me levanto*, *te levantas*, *se levanta*, *nos levantamos*, *os levantáis*, *se levantan*.",
  "Regelmäßig heißt es *hablé*, *habló* – mit Strich. Die unregelmäßigen dagegen nie: *tuve*, *tuvo*, *hice*, *hizo*, *dije*, *dijo*. Fehlt der Akzent, ist das Verb unregelmäßig. Ein verlässliches Erkennungszeichen.": "Regular forms are *hablé*, *habló* – with an accent. The irregular ones never do: *tuve*, *tuvo*, *hice*, *hizo*, *dije*, *dijo*. If the accent is missing, the verb is irregular. A reliable sign.",
  "Regelmäßige Verben auf -ar im Präsens": "Regular -ar verbs in the present tense",
  "Regelmäßige Verben auf -er und -ir": "Regular verbs ending in -er and -ir",
