  "Relativsätze mit *que* und *donde*, Superlative mit *el más … de*, Vergleiche mit *tan … como*. Ab hier sagst du nicht mehr nur „Das Hotel ist gut\", sondern „Das Hotel, in dem wir waren, war das beste der Stadt\".": "Relative clauses with *que* and *donde*, superlatives with *el más … de*, comparisons with *tan … como*. Now you can say not just \"The hotel is good,\" but \"The hotel where we stayed was the best in the city.\"",
