  "Richtungsangaben verstehen": "Understanding directions",
  "Römer (200 v. Chr. bis 400), Westgoten, Araber (711 bis 1492), dann das christliche Königreich. Jede Schicht hinterließ Spuren in Sprache und Architektur – deshalb steht in Córdoba eine Kathedrale in einer Moschee.": "Romans (200 BC to 400 AD), Visigoths, Arabs (711 to 1492), then the Christian kingdom. Each layer left traces in language and architecture – that's why there's a cathedral inside a mosque in Córdoba.",
