  "Rund 200 Millionen Menschen sagen „vos“ statt „tú“ – in Argentinien, Uruguay, Paraguay und weiten Teilen Mittelamerikas.": "Around 200 million people say \"vos\" instead of \"tú\" – in Argentina, Uruguay, Paraguay, and much of Central America.",
  "Rund die Hälfte aller spanischen Verben endet auf -ar. Wer diese sechs Endungen kann, kann Tausende von Wörtern beugen.": "About half of all Spanish verbs end in -ar. If you know these six endings, you can conjugate thousands of words.",
