  "Sag „gracias\" erst, wenn du wirklich aufhören willst. Wer sich höflich bedankt, während er weitertrinken möchte, ist aus der Runde – ohne es gemerkt zu haben.": "Say \"gracias\" only when you really want to stop. If you politely thank while wanting to continue, you're out of the round—without realizing it.",
