  "Salsa, Merengue, Bachata und Reggaetón kommen aus Kuba, der Dominikanischen Republik und Puerto Rico. Diese Musik hört man heute in Madrid häufiger als Flamenco – und für Lernende ist sie die bessere Übung.": "Salsa, Merengue, Bachata, and Reggaetón come from Cuba, the Dominican Republic, and Puerto Rico. Today, you hear this music in Madrid more often than Flamenco – and for learners, it's better practice.",
