  "Sie ist gerade nicht da, sie ist weg. Soll ich ihr etwas ausrichten?": "She's not here right now, she's out. Should I tell her something?",
  "Sie ist im Schrank, hinter den Mänteln.": "It's in the closet, behind the coats.",
  "Sie ist in der Schule. Sie arbeitet bis fünf.": "She's at school. She works until five.",
  "Sie ist jung, weiß aber viel.": "She is young but knows a lot.",
  "Sie ist klein, aber es gibt einen schönen Balkon.": "It's small, but there's a nice balcony.",
  "Sie ist klein, aber sehr stark.": "She's short but very strong.",
  "Sie ist mit ihrer Arbeit zufrieden.": "She's happy with her job.",
  "Sie ist neben der Bank, gegenüber der Haltestelle.": "It's next to the bank, across from the stop.",
  "Sie ist sauer auf mich.": "She's mad at me.",
  "Sie ist traurig, weil sie weggeht.": "She's sad because she's leaving.",
  "Sie kommen am Nachmittag an.": "They arrive in the afternoon.",
  "Sie kommen sehr gut miteinander aus.": "They get along very well.",
  "Sie kommt fast immer, meist als *¿Cuál es su expectativa salarial?* Wer keine Zahl nennen will, sagt *Me gustaría conocer primero la banda salarial del puesto* – die Gehaltsspanne der Stelle. Das ist eine akzeptierte Gegenfrage.": "It almost always comes up, usually as *¿Cuál es su expectativa salarial?* If you don't want to name a number, say *Me gustaría conocer primero la banda salarial del puesto* – the salary range for the position. This is an accepted counter-question.",
  "sie lebten glücklich": "they lived happily",
