  "Sie war nicht süß und keine Tafel. Sie war ein bitteres Getränk, manchmal mit Chili, und wurde kalt serviert. Der Zucker kam später, aus Europa.": "It wasn't sweet and not a bar. It was a bitter drink, sometimes with chili, served cold. Sugar came later, from Europe.",
