  "Stimmungen ausdrücken": "Expressing emotions",
  "stören": "bother",
  "Strand, Sonne, Sicherheit": "Beach, Sun, Safety",
  "Streich das o und setz a: haga.": "Drop the o and add a: haga.",
  "Streich das. Klingt nach einem anderen Jahrhundert.": "Scratch that. Sounds like another century.",
  "Streiche *-er* und hänge an: *com-o*, *com-es*, *com-e*, *com-emos*, *com-éis*, *com-en*. Bis auf *nosotros* und *vosotros* sind es dieselben Vokale wie bei *-ar*, nur mit *e* statt *a*.": "Drop *-er* and add: *com-o*, *com-es*, *com-e*, *com-emos*, *com-éis*, *com-en*. Except for *nosotros* and *vosotros*, the vowels are the same as with *-ar*, just with *e* instead of *a*.",
  "Streiche die Endung *-ar* und hänge an, wer spricht: *habl-o*, *habl-as*, *habl-a*, *habl-amos*, *habl-áis*, *habl-an*. Diese sechs Endungen gelten für jedes regelmäßige *-ar*-Verb – bei *trabajar*, *estudiar* und *cocinar* genauso.": "Remove the ending *-ar* and add who is speaking: *habl-o*, *habl-as*, *habl-a*, *habl-amos*, *habl-áis*, *habl-an*. These six endings apply to every regular *-ar* verb – just like *trabajar*, *estudiar*, and *cocinar*.",
  "Streit & Versöhnung": "Arguments & Reconciliation",
  "streiten": "argue",
  "Streng genommen: *debe de estar* = er ist wohl (Vermutung), *debe estar* = er muss dort sein (Pflicht). Im gesprochenen Spanisch fällt das *de* oft weg, und der Zusammenhang klärt es. Verstehen musst du beides, verwenden reicht die Vermutung.": "Strictly speaking: *debe de estar* = he is probably there (assumption), *debe estar* = he must be there (obligation). In spoken Spanish, the *de* often drops, and context clarifies it. You need to understand both, but using the assumption is enough.",
