  "Traditionell bringen nicht der Weihnachtsmann, sondern die Heiligen Drei Könige die Geschenke – am Morgen des 6. Januar. Kinder stellen abends Schuhe raus und Wasser für die Kamele. Papá Noel kam erst später dazu.": "Traditionally, it's not Santa Claus but the Three Wise Men who bring gifts – on the morning of January 6th. Children leave out shoes and water for the camels the night before. Santa Claus was a later addition.",
  "Träfen *le* und *lo* aufeinander, ergäbe das *le lo* – das spricht sich schlecht. Deshalb wird *le* zu *se*: *Se lo doy* statt *le lo doy*. Dieselbe Regel bei *les*: *Se lo mando a mis padres.*": "If *le* and *lo* were to meet, you'd get *le lo* – which is awkward to say. So, *le* changes to *se*: *Se lo doy* instead of *le lo doy*. The same rule applies with *les*: *Se lo mando a mis padres.*",
