  "Viel Glück!": "Good luck!",
  "Viele arbeiten von neun bis vierzehn Uhr, machen zwei Stunden Pause und dann bis achtzehn oder neunzehn Uhr weiter. Die *jornada intensiva* ohne lange Pause gibt es meist nur im Sommer – und sie gilt als Privileg.": "Many work from nine to two, take a two-hour break, and then continue until six or seven. The *jornada intensiva* without a long break usually only happens in summer – and it's considered a privilege.",
  "Viele Bars nehmen unter zehn Euro keine Karte. *¿Tienes suelto?* ist deshalb eine Alltagsfrage. Und wer mit einem Fünfziger einen Kaffee zahlen will, erntet ein *¿No tienes más pequeño?*": "Many bars don't accept cards for amounts under ten euros. *¿Tienes suelto?* is a common question. And if you try to pay for a coffee with a fifty, expect a *¿No tienes más pequeño?*",
  "viele Grüße": "regards",
  "Viele Grüße, Tom.": "Best regards, Tom.",
  "Viele ja, zwei oder drei ganze Wochen.": "Many do, for two or three whole weeks.",
  "Viele kleine Bars in Spanien nehmen erst ab zehn Euro Karte – ein paar Münzen in der Tasche sind Pflicht.": "Many small bars in Spain only accept cards for amounts over ten euros – always have some coins on you.",
  "Viele Spanier nennen zuerst ihre Region und dann erst Spanien – „soy gallego“ kommt oft vor „soy español“.": "Many Spaniards mention their region before Spain – \"soy gallego\" often comes before \"soy español\".",
  "Viele spanische Museen sind an einem festen Wochentag oder in der letzten Stunde gratis – nachfragen lohnt sich immer.": "Many Spanish museums are free on a specific weekday or during the last hour – it's always worth asking.",
  "Viele Wendungen gelten nur in Spanien. *Estar como una cabra* versteht man in Mexiko, benutzt es aber nicht. Umgekehrt sagt man dort *estar bien loco*. Redewendungen sind das Regionalste an einer Sprache.": "Many expressions are specific to Spain. *Estar como una cabra* is understood in Mexico but not used. Conversely, they say *estar bien loco* there. Idioms are the most regional part of a language.",
  "Viele. Coche und carro, zumo und jugo, patata und papa.": "Lots. Coche and carro, zumo and jugo, patata and papa.",
