  "Vierhundert Euro. Schau mich nicht so an!": "Four hundred euros. Don't look at me like that!",
  "Vierhundert Millionen Menschen, zwanzig Länder, ein seseo statt des z-Lauts, *vos* statt *tú*, *carro* statt *coche*. Nichts davon ist falsch. Wer das weiß, versteht beim Reisen mehr – und traut sich, den eigenen Akzent stehen zu lassen.": "Four hundred million people, twenty countries, a seseo instead of the 'th' sound, *vos* instead of *tú*, *carro* instead of *coche*. None of this is wrong. Knowing this helps you understand more when traveling – and gives you confidence to keep your own accent.",
