  "Von früher, als sie jung war. Sie hat zwanzig Jahre in Argentinien gelebt.": "About the past, when she was young. She lived in Argentina for twenty years.",
  "Von gestern und von damals erzählen, Missgeschicke schildern, Gesagtes weitergeben, Vermutungen äußern, Gefühle zum Erlebten benennen und eine Geschichte über mehrere Minuten halten. Das ist der Sprung von A2 zu B1.": "Talk about past events and mishaps, report speech, express assumptions, name feelings about experiences, and maintain a story for several minutes. This is the leap from A2 to B1.",
