  "vor": "in front of",
  "Vor Adjektiven steht *tan … como*: *tan caro como el hotel*. Vor Substantiven und nach Verben steht *tanto*: *tanto dinero como*, *No cuesta tanto como pensaba*. Verneint heißt es einfach „weniger als“.": "Before adjectives, use *tan … como*: *tan caro como el hotel*. Before nouns and after verbs, use *tanto*: *tanto dinero como*, *No cuesta tanto como pensaba*. In negative, it's simply “less than.”",
  "vor allem": "above all",
  "Vor allem darüber nachdenkend, wie dumm ich gewesen war.": "Mostly thinking about how silly I'd been.",
  "Vor allem: Gib nicht auf.": "Above all, don't give up.",
  "Vor dem gebeugten Verb": "Before the conjugated verb",
  "vor dem Kino": "in front of the cinema",
  "Vor der Prüfung zitterte ich wie Espenlaub.": "Before the exam, I was a nervous wreck.",
  "vor drei Tagen": "three days ago",
  "Vor drei Tagen sprach ich mit ihr.": "Three days ago, I talked to her.",
  "Vor einem Ort bedeutet *ir a* schlicht „gehen nach“: *Voy a Madrid*, *Voy al cine* (a + el = al). Vor einem Verb wird daraus die Zukunft: *Voy a comer*. Dieselben zwei Wörter, zwei Bedeutungen – der Rest des Satzes entscheidet.": "Before a place, *ir a* simply means \"to go to\": *Voy a Madrid*, *Voy al cine* (a + el = al). Before a verb, it turns into the future tense: *Voy a comer*. Same two words, two meanings – the rest of the sentence decides.",
  "Vor männlichen Wörtern wird *uno* zu *un*: *un café*, aber *una cerveza*.": "Before masculine words, *uno* becomes *un*: *un café*, but *una cerveza*.",
  "Vor Menschen sprechen": "Speaking in Public",
