  "Warum?": "Why?",
  "Was aber bleibt, sind die Zeiten. In Spanien isst man gegen halb drei zu Mittag und gegen neun oder später zu Abend. Für einen Deutschen ist das immer noch sehr spät.": "What remains are the times. In Spain, people have lunch around half-past two and dinner around nine or later. For an English speaker, that's still quite late.",
