  "Was die Besucher am meisten überrascht: Die Tiere haben keine Angst. Sie haben nie gelernt, dass der Mensch gefährlich sein kann, also bleiben sie ruhig.": "What surprises visitors the most: The animals aren't afraid. They've never learned that humans can be dangerous, so they stay calm.",
