  "Was für einen Tag ich heute habe!": "What a day I'm having!",
  "Was gerade passiert ist, berichtest du im Perfekt: *Mi maleta no ha llegado.* *El vuelo se ha retrasado.* *Han perdido mi equipaje.* Das passt genau – es ist heute geschehen und wirkt noch nach.": "When talking about something that just happened, use the present perfect: *Mi maleta no ha llegado.* *El vuelo se ha retrasado.* *Han perdido mi equipaje.* It fits perfectly – it happened today and still affects you.",
