  "Was stellt sich am Ende heraus?": "What turns out in the end?",
  "Was von einem unregelmäßigen Verb abgeleitet ist, bleibt unregelmäßig: *deshacer → deshecho*, *devolver → devuelto*, *descubrir → descubierto*. Man lernt also nicht acht Formen, sondern acht Familien.": "What is derived from an irregular verb remains irregular: *deshacer → deshecho*, *devolver → devuelto*, *descubrir → descubierto*. So, you're not just learning eight forms, but eight families.",
  "Was vorher war": "What happened before",
  "Was währenddessen lief": "What Was Happening Meanwhile",
