  "Wegangaben mit seguir, girar und cruzar": "Directions using seguir, girar, and cruzar",
  "wehtun": "to hurt",
  "Weihnachten": "Christmas",
  "Weihnachten verbringe ich mit meiner Familie.": "I spend Christmas with my family.",
  "weil": "because",
  "Weil dein Satz verneint ist. Mit „también“ würdest du das Gegenteil sagen.": "Because your sentence is negative. Using \"también\" would mean the opposite.",
  "Weil du Wasser hattest. Das bringt Unglück.": "Because you had water. That's bad luck.",
  "Weil es der Regel nicht folgt. Normalerweise würde man „cafe“ als CA-fe sprechen.": "Because it doesn't follow the rule. Normally, you'd say 'CA-fe'.",
  "Weil es gestern war. Gestern ist vorbei.": "Because it was yesterday. Yesterday is over.",
  "Weil es heute war. Heute ist noch nicht vorbei.": "Because it was today. Today isn't over yet.",
  "Weil es noch nicht passiert ist.": "Because it hasn't happened yet.",
  "Weil ganze Nachbarschaften dieselbe Nummer kaufen, gewinnen die Nachbarn oft gemeinsam – und wer als Einziger nicht mitgemacht hat, hat einen sehr langen Tag.": "Since whole neighborhoods buy the same number, neighbors often win together – and anyone who didn't join in has a very long day.",
  "Weil ich davon spreche, wie sie heute schmeckt. „Es rica“ klänge nach Geld.": "Because I'm talking about how it tastes today. \"Es rica\" would sound like money.",
  "Weil ich gern sehe, wie Menschen lernen.": "Because I like seeing people learn.",
  "Weil la llave weiblich ist. Der Artikel ändert sich mit dem Wort.": "Because \"la llave\" is feminine. The article changes with the word.",
  "Weil man dich versteht. Das ist nicht üblich.": "Because people understand you. It's not common.",
  "Weil man vom *yo*-Stamm ausgeht, wandern Unregelmäßigkeiten mit: *tengo → tenga*, *vengo → venga*, *hago → haga*, *digo → diga*, *conozco → conozca*. Wer die *yo*-Form kennt, kennt den Subjuntivo.": "Since you start with the *yo* form, any irregularities carry over: *tengo → tenga*, *vengo → venga*, *hago → haga*, *digo → diga*, *conozco → conozca*. If you know the *yo* form, you know the subjunctive.",
  "Weil wir zwei Frauen sind. Mit einem Mann wäre es „nosotros“.": "Because we're two women. With a man, it would be 'nosotros'.",
  "Wein, weil davon zu wenig da ist": "Wine, because there's not much of it.",
  "Wein? Bier?": "Wine? Beer?",
  "weiß": "white",
  "Weiß nicht, vor Kurzem. Wir sind hier nicht genau.": "I don't know, a short while ago. We're not precise here.",
  "Weiß nicht, wir werden sehen.": "I don't know, we'll see.",
  "Weiße Parklinien: kostenlos. Blaue: gebührenpflichtig, Ticket ziehen. Grüne: nur für Anwohner. Gelbe: absolutes Halteverbot. Wer die Farben kennt, spart sich die *multa*.": "White parking lines: free. Blue: paid, get a ticket. Green: residents only. Yellow: no stopping at all. Knowing the colors saves you from a *multa* (fine).",
  "Weißt du ein Wort nicht? *¿Me pone esto?* („Geben Sie mir das?\") plus Fingerzeig funktioniert auf jedem Markt der Welt.": "Don't know a word? *¿Me pone esto?* (\"Can you give me this?\") plus pointing works at any market in the world.",
