  "Weniger? Und ist die Qualität schlechter?": "Cheaper? Is the quality worse?",
  "wenn": "if",
  "Wenn das passiert": "When that happens",
  "Wenn die Stellung die Bedeutung ändert": "When Position Changes Meaning",
  "Wenn du in Spanien eingeladen bist und nach dem Essen aufstehst, wirkt das leicht so, als hättest du es eilig wegzukommen. Sitzenbleiben ist die Höflichkeit.": "If you're invited in Spain and stand up after eating, it might seem like you're in a rush to leave. Staying seated is polite.",
  "Wenn du jemanden fragst, wie es ihm geht, antwortet er „pura vida\". Wenn du dich bedankst, sagt er „pura vida\". Wenn etwas schiefgeht, sagt jemand „pura vida\" und macht weiter.": "If you ask someone how they're doing, they reply \"pura vida.\" If you thank them, they say \"pura vida.\" If something goes wrong, someone says \"pura vida\" and moves on.",
  "Wenn du lernst, bestehst du die Prüfung.": "If you study, you will pass the exam.",
  "Wenn du nicht verstehst, frag.": "If you don't understand, ask.",
  "wenn du willst": "if you want",
  "Wenn du willst, begleite ich dich.": "If you want, I'll go with you.",
  "Wenn du zweifelst, mach es nicht.": "If you're unsure, don't do it.",
  "Wenn er nicht kommt, fangen wir an.": "If he doesn't come, then we'll start.",
  "Wenn er nur kommen könnte, aber er ist in Berlin.": "If only he could come, but he's in Berlin.",
  "Wenn es mal knirscht": "When Things Get Tense",
  "Wenn es nicht klappt": "When things don't work out",
  "wenn es regnet": "if it rains",
  "Wenn es regnet, bleiben wir zu Hause.": "If it rains, we'll stay home.",
