  "Widersprechen ist erlaubt": "Disagreement is allowed",
  "Widersprechen, ohne zu streiten": "Disagreeing without arguing",
  "Widerspruch gilt in Spanien nicht als Angriff – wer nie widerspricht, wirkt eher gleichgültig als höflich.": "In Spain, disagreement isn't seen as an attack – if you never disagree, you might seem indifferent rather than polite.",
  "Wie „hör mal\". Deshalb nannten sie Guevara Che.": "Like \"hey.\" That's why they called Guevara Che.",
  "Wie „un viejo amigo“?": "Like \"un viejo amigo\"?",
  "Wie alt bist du?": "How old are you?",
  "Wie alt ist deine Tochter?": "How old is your daughter?",
  "Wie ärgerlich. Und Carmen hatte keinen Zweitschlüssel?": "How annoying. And Carmen didn't have a spare key?",
  "Wie bei „venga\", wenn du siezt?": "Like with \"venga,\" when you're being formal?",
  "Wie bei uns: *¡Qué calor!* („Was für eine Hitze!\") ist der einfachste Gesprächseinstieg Spaniens – im Aufzug, an der Bushaltestelle, überall.": "Just like for us: *¡Qué calor!* (\"What heat!\") is Spain's simplest conversation starter – in the elevator, at the bus stop, everywhere.",
  "Wie beim Du-Befehl: *Dígame* (sagen Sie mir), *Perdóneme* (entschuldigen Sie mich). Verneint wandert es nach vorn: *No se preocupe*, *No me lo diga*.": "Like with the informal command: *Dígame* (tell me), *Perdóneme* (forgive me). In negative commands, it moves to the front: *No se preocupe* (don't worry), *No me lo diga* (don't tell me).",
