  "Wie im Deutschen „die Hosen“ stehen einige Kleidungsstücke im Plural: *los pantalones*, *las gafas* (Brille), *los vaqueros* (Jeans). Das Verb geht mit: *Los pantalones son caros*, nicht *es caro*.": "Just like in English \"pants,\" some clothing items are plural in Spanish: *los pantalones*, *las gafas* (glasses), *los vaqueros* (jeans). The verb agrees: *Los pantalones son caros*, not *es caro*.",
