  "wo": "where",
  "Wo arbeitest du und wann fängst du an?": "Where do you work and when do you start?",
  "Wo arbeitest du?": "Where do you work?",
  "Wo beide Wege zusammenlaufen – die Vergangenheit": "Where Paths Meet: The Past",
  "Wo bist du?": "Where are you?",
  "Wo das Deutsche „meine Hände“ sagt, sagt das Spanische *las manos*: *Me lavo las manos.* *Me duele la cabeza.* Das *me* sagt schon, wessen Kopf gemeint ist – ein *mi cabeza* klingt, als hättest du mehrere zur Auswahl.": "Where English says \"my hands,\" Spanish uses *las manos*: *Me lavo las manos.* *Me duele la cabeza.* The *me* already indicates whose head it is – saying *mi cabeza* sounds like you have several to choose from.",
  "Wo das Deutsche „sein“ nimmt, nimmt das Spanische oft *tener*: *tener hambre* (Hunger haben), *tener sed*, *tener frío* (frieren), *tener calor*, *tener sueño* (müde sein), *tener prisa*, *tener miedo* (Angst haben).": "Where English uses \"to be,\" Spanish often uses *tener*: *tener hambre* (to be hungry), *tener sed* (to be thirsty), *tener frío* (to be cold), *tener calor* (to be hot), *tener sueño* (to be sleepy), *tener prisa* (to be in a hurry), *tener miedo* (to be afraid).",
  "Wo das Deutsche zwischen der, die, das und den unterscheidet, hat das Spanische nur *que*: *el hombre que vino*, *la casa que compré*, *los libros que leo*. Kein Geschlecht, kein Fall – eine der wenigen Vereinfachungen.": "Where English distinguishes between who, which, and that, Spanish just uses *que*: *el hombre que vino*, *la casa que compré*, *los libros que leo*. No gender, no case – one of the few simplifications.",
  "Wo derselbe Gegenstand anders heißt": "Different Names for the Same Thing",
  "Wo Deutsche eine Mail schreiben und drei Tage warten, greift man in Spanien zum Hörer. Ein Anruf gilt nicht als Störung, sondern als effizient. Danach kommt die Mail – als Bestätigung, nicht als Ersatz.": "Where English speakers might send an email and wait for a few days, in Spain, people pick up the phone. A call is seen as efficient, not intrusive. The email follows – as confirmation, not as a substitute.",
  "Wo Deutsche einen Plan erwarten, sagen Spanier oft *ya veremos*. Das ist keine Ausflucht, sondern eine Haltung: Man legt sich nicht fest, was man nicht kennt. Wer es hört, sollte nicht nachbohren – die Antwort ist die Antwort.": "Where English speakers might expect a plan, Spaniards often say *ya veremos*. It's not an evasion, but an attitude: You don't commit to what you don't know. If you hear it, don't press further – the answer is the answer.",
