  "Wörter auf *-z* schreiben in der Mehrzahl *-ces*: *la voz → las voces*, *el lápiz → los lápices*, *la vez → las veces*. Gesprochen ändert sich fast nichts – es ist eine Schreibregel, keine Lautregel.": "Words ending in *-z* change to *-ces* in plural: *la voz → las voces*, *el lápiz → los lápices*, *la vez → las veces*. The pronunciation barely changes – it's a spelling rule, not a pronunciation rule.",
  "Wörter beim ersten Lesen richtig aussprechen": "Pronouncing words correctly on first sight",
  "Wörter griechischen Ursprungs auf -ma sind männlich: el problema, el tema, el idioma – trotz der Endung auf -a.": "Words of Greek origin ending in -ma are masculine: el problema, el tema, el idioma – despite ending in -a.",
  "Wörter im Satz": "Words in a sentence",
