  "Wörter, die ihre Bedeutung wechseln": "Words that change meaning",
  "Wörtlich „nicht dass es sein möge, dass\". Gemeint ist: pass auf, sonst passiert etwas. *Sal ya, no vaya a ser que pierdas el tren.* Immer mit Subjuntivo, und sehr gebräuchlich im Alltag.": "Literally \"not that it may be that.\" It means: be careful, or something might happen. *Sal ya, no vaya a ser que pierdas el tren.* Always with Subjunctive, and very common in everyday speech.",
