  "Zahl + Wort + *por favor*: *Dos cervezas, por favor* – damit klingst du sofort wie ein Local!": "Number + word + *por favor*: *Dos cervezas, por favor* – and you'll sound like a local right away!",
  "Zahlen": "Numbers",
  "Zahlen bis 1.000": "Numbers up to 1,000",
