  "Zahlen erläutern": "Explaining numbers",
  "Zahlen wirken: *Es la tercera vez*, *Llevamos tres días*, *Pagué ochenta euros*. Wer Fakten nennt, bekommt eher eine Lösung als wer sich empört. Lautstärke gilt in Spanien nicht als Nachdruck, sondern als Kontrollverlust.": "Numbers make an impact: *Es la tercera vez*, *Llevamos tres días*, *Pagué ochenta euros*. Stating facts gets you a solution more often than getting upset. In Spain, loudness is seen as losing control, not emphasis.",
