  "Zu den Präpositionen aus Lektion 18 kommen zwei senkrechte dazu: *encima de* (auf, über) und *debajo de* (unter). *El libro está encima de la mesa.* *Los zapatos están debajo de la cama.*": "To the prepositions from lesson 18, add two vertical ones: *encima de* (on, above) and *debajo de* (under). *El libro está encima de la mesa.* *Los zapatos están debajo de la cama.*",
  "Zu einer Gruppe sagt man in Amerika immer *ustedes* – auch zu Freunden. Die *vosotros*-Formen versteht man, benutzt sie aber nie. Wer nur Amerika bereist, kann sich diese sechs Formen sparen.": "In the Americas, you always use *ustedes* for a group – even with friends. The *vosotros* forms are understood but never used. If you're only traveling in the Americas, you can skip these six forms.",
  "zu Fuß": "on foot",
