  "Zu Kollegen: *Hola Ana,* … *Un saludo.* Zu Externen: *Buenos días:* … *Un cordial saludo.* Zu Behörden: *Estimados señores:* … *Atentamente.* Wer die mittlere Form nimmt, liegt fast immer richtig.": "To colleagues: *Hola Ana,* … *Un saludo.* To external contacts: *Buenos días:* … *Un cordial saludo.* To authorities: *Estimados señores:* … *Atentamente.* Using the middle form is almost always a safe choice.",
