  "Zum Fest gehört der „roscón de Reyes\", ein Kranzkuchen. Darin ist eine Bohne versteckt – wer sie findet, muss den Kuchen im nächsten Jahr bezahlen.": "Part of the celebration is the \"roscón de Reyes,\" a ring-shaped cake. A bean is hidden inside—whoever finds it must pay for the cake next year.",
