  "Zwanzig Minuten Gespräch bringen mehr als zwei Stunden Vokabellernen – weil man dabei merkt, was fehlt. *Intercambios* gibt es in jeder größeren Stadt: Eine Stunde Spanisch, eine Stunde Deutsch, beide gewinnen.": "Twenty minutes of conversation is worth more than two hours of vocabulary study—because you realize what's missing. *Intercambios* are available in most big cities: One hour of Spanish, one hour of English, both benefit.",
