  "Zwei Wochen. Ihr Besuch hat mich sehr gefreut.": "Two weeks. I really enjoyed her visit.",
  "Zwei Wörter, eine Sache": "Two words, one thing",
  "Zwei Wörter, mit denen man in Costa Rica fast jedes Gespräch führen kann.": "Two words you can use for almost any conversation in Costa Rica.",
  "Zwei Zeichen, ein Zweck": "Two symbols, one purpose",
  "Zwei: mein Zimmer und Carmens. Und ein Bad.": "Two: my room and Carmen's. And a bathroom.",
  "Zweifel verlangt ihn immer": "Doubt always demands it",
  "zweihundert": "two hundred",
  "Zweiundzwanzig Lektionen lang ging es um einen einzigen Satz: wer du bist. *Me llamo…*, *soy de…*, *tengo… años*, *vivo en…* Damit hältst du dein erstes Gespräch durch – und mehr braucht der Anfang nicht.": "For twenty-two lessons, it was all about one sentence: who you are. *Me llamo…*, *soy de…*, *tengo… años*, *vivo en…* With this, you can hold your first conversation – and that's all you need to start.",
  "zwischen": "between",
  "Zwischen „debe de estar“ und „debe estar“ liegt der Unterschied zwischen Vermutung und Pflicht – im Alltag verschwimmt er allerdings.": "The difference between \"debe de estar\" and \"debe estar\" is between guessing and obligation – but in everyday use, it blurs.",
  "Zwischen „ich weiß es“ und „keine Ahnung“ liegt *me suena*: kommt mir bekannt vor, ich komme nur nicht drauf. Sehr gebräuchlich – und höflicher als ein glattes *No sé*.": "Between \"I know it\" and \"no idea\" lies *me suena*: it sounds familiar, but I can't quite place it. Very common – and more polite than a flat *No sé*.",
  "Zwischen *haber* und Partizip darf nichts stehen: *No he comido todavía* – nicht *he no comido*. Und das Partizip verändert sich nie: immer *comido*, egal wer spricht. Anders als im Deutschen wird es nicht ans Ende geschoben.": "Nothing can come between *haber* and the participle: *No he comido todavía* – not *he no comido*. And the participle never changes: always *comido*, no matter who is speaking. Unlike in English, it doesn't move to the end.",
  "Zwischen *no es simpático* und *es simpático* liegt viel Raum: *un poco* (schwächt ab, meist bei Negativem), *bastante* (ziemlich), *muy* (sehr), *-ísimo* (überaus). *Es simpatiquísimo* ist die stärkste Form – und sehr spanisch.": "Between *no es simpático* and *es simpático*, there's a lot of room: *un poco* (a little, often used to soften negatives), *bastante* (quite), *muy* (very), *-ísimo* (extremely). *Es simpatiquísimo* is the strongest form – and very Spanish.",
  "Zwischen 14 und 17 Uhr ist die Sonne in Spanien im Sommer gefährlich stark. Einheimische gehen morgens oder ab fünf an den Strand. Wer mittags dort liegt, ist mit Sicherheit Tourist – und abends rot.": "Between 2 and 5 PM, the sun in Spain is dangerously strong in summer. Locals go to the beach in the morning or after five. If you're there at midday, you're definitely a tourist – and you'll be red by evening.",
  "Zwischen 14 und 17 Uhr schließen viele Läden, Kirchen und kleinere Museen. Wer diese drei Stunden nicht einplant, steht vor verschlossenen Türen. Genau dafür ist die *siesta* die richtige Zeit zum Essen.": "Between 2 and 5 PM, many shops, churches, and smaller museums close. If you don't plan for these three hours, you'll find closed doors. That's exactly when the *siesta* is the perfect time to eat.",
  "Zwischen A1 und A2 geht es schnell, danach scheinbar gar nicht mehr. Das täuscht: Der Fortschritt verlagert sich vom Wortschatz zur Feinheit. Man merkt ihn erst, wenn man ein Gespräch führt, das vor drei Monaten unmöglich war.": "Between A1 and A2, progress feels fast, but then it seems to stall. Don't be fooled: Progress shifts from vocabulary to nuances. You'll notice it when you have a conversation that seemed impossible three months ago.",
  "Zwischen beiden Formen wählen": "Choose between the two forms",
  "Zwischen beiden Vergangenheiten wählen": "Choosing between the two past tenses",
  "Zwischen dreißig- und fünfunddreißigtausend.": "Between thirty and thirty-five thousand.",
  "Zwischen elf und halb zwölf verlassen ganze Abteilungen das Gebäude für Kaffee und ein Sandwich. Das ist kein Schwänzen, sondern Teil des Arbeitstags – dort werden Dinge besprochen, die in keiner Besprechung vorkommen.": "Between eleven and eleven-thirty, entire departments leave the building for coffee and a sandwich. It's not slacking off, but part of the workday – where things are discussed that don't come up in meetings.",
  "Zwischen Galicien und Andalusien liegen andere Sprachen, anderes Klima, andere Küche und andere Feste. Wer „typisch spanisch\" sagt, meint meist Andalusien – Flamenco und Stierkampf sind im Norden fast so fremd wie in Deutschland.": "Between Galicia and Andalusia, there are different languages, climates, cuisines, and festivals. When people say \"typical Spanish,\" they often mean Andalusia – flamenco and bullfighting are almost as foreign in the north as they are in England.",
  "Zwischen Lob und Spott unterscheiden": "Distinguishing between praise and sarcasm",
  "Zwischen Pflicht und Empfehlung unterscheiden": "Distinguishing between obligation and suggestion",
  "Zwischen tú und usted sicher wählen": "Confidently choosing between tú and usted",
  "Zwischenfragen gehören dazu": "Questions in between are part of it",
  "Zwischenfragen mitten im Vortrag sind in Spanien üblich – wer sie abwehrt, wirkt steif.": "Asking questions during a presentation is common in Spain – if you dismiss them, you might seem stiff.",
  "Zwölf Trauben in zwölf Sekunden": "Twelve grapes in twelve seconds",
  "Zwölf Verben kürzen den Stamm": "Twelve verbs shorten the stem",
